  focus:'반복되는 끌림과 이별의 이유를 여덟 글자에서 찾아, 다음 관계의 문장을 바꿔드려요.',
  intro:'연애 패턴은 취향의 문제가 아니라 구조의 문제예요. {name} 님이 끌리는 사람의 결, 다가가는 방식, 지칠 때 물러서는 지점을 여덟 글자에서 찾아 정리했습니다.',
