   ohaeng:'두 사람의 오행을 합쳐보면 서로에게 없는 기운이 보여요. 내게 없는 것을 상대가 가지고 있으면 끌림이 되고, 둘 다 없는 것은 생활에서 부딪히는 지점이 됩니다. {yongko} 쪽은 두 사람이 함께 채워가면 좋아요.',
   love:'커플 궁합의 핵심은 다툼의 방식이에요. 이 사주는 감정이 올라오면 말이 먼저 나가는 편이라, 상대가 조용히 정리하는 사람이면 오해가 오래갑니다. 싸운 뒤 30분을 비워두는 규칙 하나로 갈등의 절반이 줄어요.',
   money:'두 사람의 돈의 결도 궁합의 일부예요. 한쪽이 쓰는 사람, 한쪽이 모으는 사람이면 역할이 분명해 오히려 안정됩니다. 둘 다 쓰는 쪽이면 공동 통장의 규칙을 먼저 정하세요.',
   health:'함께 지낼 때 컨디션이 엇갈리는 시기를 알면 좋아요. 두 사람의 부족한 오행이 겹치는 계절에는 서로 예민해지기 쉬우니, 그때는 일정을 줄이고 잠을 먼저 챙기세요.',
   daeun:'두 사람의 대운이 같은 방향을 보는 시기에는 결정이 빠르게 진행돼요. 결혼·이사·사업처럼 큰 결정은 두 사람의 대운이 함께 움직이는 해에 하면 훨씬 수월합니다.'
