/* 탭 문장 안의 토큰 채우기 */
function fillTxt(t,R,c,input,name){
  if(!t) return '';
  var map={
    name:name,
    ilju:ILJU[R.dIdx][0],
    dm:STEM_HAN[R.dStem]+'('+STEM_KO[R.dStem]+')',
    yong:eko(c.yongEl), yongko:EL_KO[c.yongEl],
    topgrp:c.topGrp, topgod:c.topGodInGrp,
    branch:BR_HAN[R.dBranch]+'('+BR_KO[R.dBranch]+')',
    dayel:EL_KO[R.dayEl], strength:R.strength,
    daeunkey:DAEUN_KEY[tenGod(R.dStem,R.daeun[R.curDaeun].idx%10)],
    childstar:eko(input.gender==='f'?c.sikEl:c.gwanEl),
    incnt:c.grp['인성'],
    newyear:(new Date()).getFullYear()+1,
    instate:(c.grp['인성']>=3?'두터운 편':(c.grp['인성']<=1?'얇은 편':'고른 편'))
  };
  return t.replace(/\{(\w+)\}/g,function(m,k){ return (k in map)?map[k]:m; });
}

