function monthFlow(R,c,kind,n,introTxt){
  var ms=nextMonths(n||12), h='';
  if(introTxt) h+='<p class="rb-p">'+introTxt+'</p>';
  var tips=MONTH_TIPS[kind]||MONTH_TIPS.general;
  var used={}, lastTip='', lastRel='';
  for(var i=0;i<ms.length;i++){
    var mo=ms[i], mp=monthPillarOf(mo.y,mo.m), g=tenGod(R.dStem,mp.stem), grp=GOD_GROUP[g];
    var rel=branchRel(R.dBranch,mp.branch), tag=monthTag(rel);
    var list=tips[grp]||[], k=used[grp]||0; used[grp]=k+1;
    var tip=list.length?list[(k+mp.branch)%list.length]:'';
    if(tip===lastTip&&list.length>1) tip=list[(k+mp.branch+1)%list.length];
    var rl=MONTH_REL_TIPS[tag]||MONTH_REL_TIPS['무난'];
    var rt=(tag==='무난'?'':rl[(i+mp.branch)%rl.length]);
    if(rt&&rt===lastRel&&rl.length>1) rt=rl[(i+mp.branch+1)%rl.length];
    var bn=MONTH_BRANCH_NOTE[mp.branch]||'';
    lastTip=tip; lastRel=rt;
    h+='<div class="rb-yr"><div class="yh"><span class="y">'+mo.y+'.'+num2(mo.m)+'</span><b>'+STEM_HAN[mp.stem]+BR_HAN[mp.branch]+'</b>'+
       '<span class="g">'+g+' · '+tag+'</span></div>'+
       '<p class="mt">'+tip+(rt?' '+rt:'')+'</p>'+
       '<p class="bn">'+bn+'</p></div>';
  }
  return h;
}

/* 대운 점수 (황금기 찾기) */
function daeunScore(R,i,c){
  var idx=R.daeun[i].idx, g=tenGod(R.dStem,idx%10), grp=GOD_GROUP[g], el=STEM_EL[idx%10];
  var s=0;
  if(grp==='재성') s+=3;
  if(grp==='관성') s+=2;
  if(grp==='식상') s+=2;
  if(grp==='인성') s+=1;
  if(el===c.yongEl) s+=3;
  if(generates(el,R.dayEl)) s+=2;
  if(GOD_GROUP[g]==='비겁'&&R.strength==='강') s+=1;
  return s;
}
function bestDaeun(R,c){
  var best=0, bs=-99;
  for(var i=0;i<R.daeun.length;i++){ var s=daeunScore(R,i,c); if(s>bs){ bs=s; best=i; } }
  return {i:best,s:bs};
}
/* 세운에서 특정 십성 그룹이 오는 해 */
function seunYearsByGroup(R,grp){
  var out=[];
  for(var i=0;i<R.seun.length;i++){
    var g=tenGod(R.dStem,R.seun[i].idx%10);
    if(GOD_GROUP[g]===grp) out.push({y:R.seun[i].year,g:g,i:i});
  }
  return out;
}
