function wongukRows(R){
  var rows=[
    ['시주',R.hIdxP],['일주',R.dIdx],['월주',R.mIdx],['년주',R.yIdx]
  ];
  var h='<div class="rb-meter">';
  for(var i=rows.length-1;i>=0;i--){
    var lab=rows[i][0], idx=rows[i][1];
    if(idx===null){ h+='<span class="rb-el"><b>'+lab+'</b> 시간 모름</span>'; continue; }
    h+='<span class="rb-el"><b>'+lab+'</b> '+STEM_HAN[idx%10]+BR_HAN[idx%12]+'</span>';
  }
  h+='</div>';
  return h;
}
function chWonguk(R,c,input,name){
  var dm=DM_DEEP[R.dStem], st=STRENGTH_TXT[R.strength];
  var g=c.gc, top=c.topGodInGrp;
  var h='';
  h+='<p class="rb-p">'+name+' 님의 원국은 년주 <b>'+STEM_HAN[R.yIdx%10]+BR_HAN[R.yIdx%12]+'</b>, 월주 <b>'+STEM_HAN[R.mIdx%10]+BR_HAN[R.mIdx%12]+'</b>, 일주 <b>'+STEM_HAN[R.dStem]+BR_HAN[R.dBranch]+'</b>'+
      (R.hIdxP!==null?', 시주 <b>'+STEM_HAN[R.hIdxP%10]+BR_HAN[R.hIdxP%12]+'</b>':'')+'으로 서 있습니다. 태어난 달은 <b>'+SEASON[R.dBranch][0]+'</b>이고, 그 계절의 공기가 이 사주의 바탕을 정했어요.</p>';
  h+=wongukRows(R);
  h+='<h4 class="rb-h">일간의 결 — '+STEM_HAN[R.dStem]+'('+STEM_KO[R.dStem]+')</h4>';
  h+='<p class="rb-p">일간은 사주에서 <b>나 자신</b>을 뜻하는 글자예요. '+STEM_HAN[R.dStem]+josaP(STEM_HAN[R.dStem],'은는')+' '+DAY_MASTER[R.dStem][0]+'의 기운으로, '+DAY_MASTER[R.dStem][1]+' 여기에 일지 '+brB(R.dBranch)+'가 앉아 <b>'+ILJU[R.dIdx][0]+'</b> 같은 결이 완성됐어요.</p>';
  h+='<p class="rb-p">'+dm.out+'<br><br>'+BR_INNER[R.dBranch]+' 그래서 처음 만난 사람이 기억하는 인상과, 오래 아는 사람이 아는 얼굴이 꽤 다릅니다.</p>';

  h+='<h4 class="rb-h">신강·신약 — 이 사주의 힘의 세기</h4>';
  h+='<p class="rb-p">일간을 도와주는 기운(같은 오행 + 나를 낳아주는 오행)이 모두 <b>'+R.support+'개</b>라, 이 사주는 <b>'+R.strength+'</b> 쪽으로 기울어 있어요. '+st.out+'</p>';
  h+='<p class="rb-p">'+st.adv+'</p>';

  h+='<h4 class="rb-h">십성 구조 — 무엇이 많은 사주인가</h4>';
  h+='<p class="rb-p">여덟 글자를 관계의 이름으로 다시 세면 이렇게 나뉩니다. 가장 두터운 것은 <b>'+c.topGrp+'</b>이고, 그 안에서 중심이 되는 별은 <b>'+top+'</b>이에요.</p>';
  h+='<ul class="rb-ul">';
  for(var i=0;i<GRP_ORDER.length;i++){
    var k=GRP_ORDER[i], n=c.grp[k];
    var on=(k===c.topGrp)?' class="on"':'';
    h+='<li'+on+'><b>'+k+' '+n+'개</b> — '+GRP_ROLE[k]+'. '+GROUP_MEAN[k]+'</li>';
  }
  h+='</ul>';
  h+='<p class="rb-p">'+GOD_DEEP[top]+' 이 별이 많은 만큼, 이 사주는 <b>'+GOD_KEY[top]+'</b>으로 사람들에게 읽힙니다.</p>';

  h+='<h4 class="rb-h">계절과 조후 — 몸이 반응하는 방식</h4>';
  h+='<p class="rb-p">'+SEASON[R.dBranch][1]+' 명리에서는 이 계절의 온도까지 함께 봅니다. 이 사주에는 '+elB(c.mostI)+' 기운이 가장 많고 '+elB(c.leastI)+' 기운이 가장 적어서, 같은 일을 해도 <b>'+EL_KO[c.mostI]+'</b> 쪽으로 힘이 쏠리고 <b>'+EL_KO[c.leastI]+'</b> 쪽에서 먼저 지칩니다.</p>';

  h+='<h4 class="rb-h">타고난 무기와 조심할 결</h4>';
  h+='<p class="rb-p">'+dm.weapon+'</p>';
  h+='<p class="rb-p">반대로 '+dm.weak+' 이 사주는 '+c.topGrp+'이 두터워 <b>'+GOD_KEY[top]+'</b>이 무기로 보이지만, 그 무기가 과해질 때 같은 지점에서 상처를 만듭니다. 무기와 약점이 같은 재료라는 걸 기억하면 사람을 대하는 태도가 조금 달라져요.</p>';
  h+='<h4 class="rb-h">이 사주를 어떻게 쓰면 좋은가</h4>';
  h+='<p class="rb-p">'+name+' 님은 '+ILJU[R.dIdx][0]+'의 결로, '+(R.strength==='강'?'힘을 밖으로 쓰는 일에서 성취가 큽니다. 안으로만 쓰면 고집이 되고, 밖으로 쓰면 사람을 움직이는 힘이 됩니다. 발표·기획·새 프로젝트처럼 밖으로 나가는 자리를 하나 두세요.':(R.strength==='약'?'혼자 버티기보다 사람과 환경의 도움을 처음부터 설계에 넣을 때 성취가 큽니다. 도움을 청하는 것이 이 사주의 실력이에요. 한 사람의 조력자를 정해두는 것만으로 결과가 달라집니다.':'상황에 따라 힘을 조절할 수 있는 사주입니다. 결정만 미루지 않으면 균형이 오래 갑니다. 작은 결정을 빨리 끝내는 습관이 힘을 모아줍니다.'))+'</p>';
  h+='<p class="rb-p">'+(R.hIdxP!==null?'시주 '+brB(R.hIdxP%12)+'까지 더해지면 말년의 결이 한층 분명해집니다. ':'시간을 몰라 시주를 비워두었어요. 자녀운과 말년의 결은 조금 더 넓게 읽어주세요. ')+'원국은 타고난 것이지만, 그 원국을 어느 방향으로 쓰느냐는 매일의 선택입니다.</p>';
  h+='<div class="rb-key"><b>원국 한 줄 정리</b><span>'+STEM_HAN[R.dStem]+BR_HAN[R.dBranch]+'일주 · '+c.topGrp+'이 두터운 '+R.strength+'한 사주 · 필요한 기운은 '+eko(c.yongEl)+'. 이 사주는 「'+GOD_KEY[top]+'」을 오래 쓰는 사람입니다.</span></div>';
  return h;
}

function daeunStrip(R){
  var strip='';
  for(var di=0;di<R.daeun.length;di++){
    var dd=R.daeun[di], dst=dd.idx%10, dbr=dd.idx%12;
    strip+='<div class="dn'+(di===R.curDaeun?' now':'')+'">'+
      '<div class="age">'+dd.from+'~'+dd.to+'세</div>'+
      '<div class="p" style="color:'+EL_COLOR[STEM_EL[dst]]+'">'+STEM_HAN[dst]+BR_HAN[dbr]+'</div>'+
      '<div class="g">'+tenGod(R.dStem,dst)+'</div>'+
    '</div>';
  }
  return '<div class="daeun-scroll">'+strip+'</div>';
}

function chGolden(R,c,input,name){
  var dn=R.daeun[R.curDaeun], g=tenGod(R.dStem,dn.idx%10);
  var bd=bestDaeun(R,c), bn=R.daeun[bd.i], bg=tenGod(R.dStem,bn.idx%10);
  var nx=R.daeun[R.curDaeun+1];
  var h='';
  h+='<p class="rb-p">사주의 그릇은 태어날 때 정해지지만, <b>언제 그 그릇을 쓰게 되는지</b>는 대운이 정합니다. '+name+' 님의 대운은 <b>'+(R.forward?'순행':'역행')+'</b>으로 흐르고, 대운수는 <b>'+R.daeunSu+'</b>예요. 10년마다 판이 한 번씩 바뀌는 셈입니다.</p>';
  h+=daeunStrip(R);
  h+='<h4 class="rb-h">지금의 10년 — '+dn.from+'~'+dn.to+'세</h4>';
  h+='<p class="rb-p">지금은 <b>'+g+'</b>의 대운이에요. '+(GOD_DAEUN[g]||'')+'</p>';
  h+='<p class="rb-p">대운의 천간은 '+elB(STEM_EL[dn.idx%10])+'의 기운이라 '+REL_NOTE[elRel(R.dayEl,STEM_EL[dn.idx%10])]+' 이 10년을 한 단어로 줄이면 <b>'+DAEUN_KEY[g]+'</b>이고, 그 힘을 어디에 쓰느냐가 다음 10년의 출발점을 바꿉니다.</p>';

  h+='<h4 class="rb-h">인생의 황금기 — '+bn.from+'~'+bn.to+'세</h4>';
  h+='<p class="rb-p">아홉 개의 대운을 사주와의 관계로 견줘보면, 가장 힘이 실리는 구간은 <b>'+bn.from+'~'+bn.to+'세의 '+STEM_HAN[bn.idx%10]+BR_HAN[bn.idx%12]+' 대운('+bg+')</b>이에요. '+(GOD_DAEUN[bg]||'')+'</p>';
  h+='<p class="rb-p">이 구간이 황금기인 이유는 세 가지예요. 첫째, 대운의 기운이 '+eko(STEM_EL[bn.idx%10])+'으로 이 사주에 필요한 '+eko(c.yongEl)+'의 결을 채워줍니다. 둘째, <b>'+bg+'</b>이 '+c.topGrp+' 중심의 원국과 부딪히지 않고 쓰임을 만들어요. 셋째, 그때가 '+bn.from+'세 전후라 생활의 기반이 이미 서 있을 나이입니다. 이 10년에는 <b>품위를 낮추는 선택</b>을 피하세요. 싼 일을 많이 하는 대신, 이름이 남는 일을 하나 붙드는 것이 이 대운을 쓰는 방법입니다.</p>';
  if(nx){
    var ng=tenGod(R.dStem,nx.idx%10);
    h+='<h4 class="rb-h">다음 대운 미리보기 — '+nx.from+'~'+nx.to+'세 · '+ng+'</h4>';
    h+='<p class="rb-p">'+(GOD_DAEUN[ng]||'')+' 대운이 바뀌는 해에는 몸도 새 환경에 적응하느라 유난히 피곤합니다. 시작 2~3년 전부터 '+eko(c.yongEl)+' 쪽으로 생활을 조금씩 옮겨두면 전환이 부드러워져요. 이사·이직·계약처럼 되돌리기 어려운 일은 대운이 바뀌는 해의 초반을 피하는 편이 안전합니다.</p>';
  }

  h+='<h4 class="rb-h">아홉 번의 10년, 한 줄씩</h4>';
  h+='<ul class="rb-ul">';
  for(var i=0;i<R.daeun.length;i++){
    var dd=R.daeun[i], dg=tenGod(R.dStem,dd.idx%10);
    var nowS=(i===R.curDaeun)?' <b>(지금)</b>':'';
    h+='<li'+(i===R.curDaeun?' class="on"':'')+'><b>'+dd.from+'~'+dd.to+'세 · '+STEM_HAN[dd.idx%10]+BR_HAN[dd.idx%12]+'('+dg+')</b> — '+DAEUN_KEY[dg]+'의 10년. '+(GOD_DAEUN[dg]||'').split('.')[0]+'.'+nowS+'</li>';
  }
  h+='</ul>';
  h+='<h4 class="rb-h">대운을 쓰는 세 가지 규칙</h4>';
  h+='<ul class="rb-ul">'+
    '<li><b>천간은 분위기, 지지는 판</b> — 대운의 천간 '+stemB(dn.idx%10)+'은 그 10년의 공기이고, 지지 '+brB(dn.idx%12)+'는 실제로 생활이 바뀌는 자리예요. 체감은 지지에서 옵니다.</li>'+
    '<li><b>전환기 2년</b> — 대운이 바뀌는 실제 변화는 그 전후 2년에 걸쳐 옵니다. 이사·이직·계약처럼 되돌리기 어려운 일은 전환기 첫해에 몰지 마세요.</li>'+
    '<li><b>황금기에는 품위</b> — 좋은 대운에는 싼 일을 많이 하기보다 이름이 남는 일을 하나 붙드세요. 그 선택이 다음 대운의 출발점을 바꿉니다.</li>'+
  '</ul>';
  h+='<p class="rb-p">대운은 좋은 것과 나쁜 것으로 나뉘지 않아요. 같은 재성 대운도 준비된 사람에게는 수입이 되고, 준비되지 않은 사람에게는 지출이 됩니다. 이 사주는 <b>'+GOD_KEY[g]+'</b>의 10년을 지나는 중이니, 그 단어를 올해의 계획에 하나 붙여보세요.</p>';
  h+='<div class="rb-key"><b>황금기를 놓치지 않으려면</b><span>'+bn.from+'세가 시작되기 1~2년 전에 「지금 하는 일을 계속할 것인가」를 한 번 정하세요. 대운은 문을 열어줄 뿐, 그 문을 지나가는 것은 그 전에 내린 결정입니다.</span></div>';
  return h;
}

function chLoveGeneral(R,c,input,name){
  return secLove(R,c,input,name)+loveExtra(R,c,input,name);
}
function loveExtra(R,c,input,name){
  var star=(input.gender==='f')?c.gwanEl:c.jaeEl;
  var h='<h4 class="rb-h">배우자상 — 어떤 사람이 오래 머무는가</h4>';
  h+='<p class="rb-p">일지 '+brB(R.dBranch)+'가 보여주는 배우자상은 <b>'+SPOUSE[R.dBranch]+'</b>이에요. '+BR_INNER[R.dBranch]+' 그래서 이 사주는 첫눈에 끌리는 사람보다 몇 번 만나야 편해지는 사람과 오래 갑니다.</p>';
  h+='<p class="rb-p">'+(input.gender==='f'?'여성 사주에서 배우자를 보는 관성은':'남성 사주에서 배우자를 보는 재성은')+' '+elB(star)+'의 기운으로 놓여 있어요. 그래서 <b>'+EL_PERSON[star]+'</b> 쪽의 사람에게 눈이 가고, 그 결이 생활에 있을 때 마음이 놓입니다.</p>';
  h+='<h4 class="rb-h">결혼 후 달라지는 것</h4>';
  h+='<p class="rb-p">이 사주는 결혼을 하면 <b>'+GOD_KEY[c.topGodInGrp]+'</b>이 가정 안에서 더 크게 작동합니다. '+GOD_DEEP[c.topGodInGrp]+' 그래서 배우자가 이 부분을 이해해주면 편안하고, 모르면 “왜 저렇게까지” 싶은 장면이 반복돼요.</p>';
  h+='<ul class="rb-ul">'+
    '<li><b>연애 때</b>는 표현이 적어도 마음이 큰 사람으로 보입니다. 말보다 오래된 약속으로 애정을 증명해요.</li>'+
    '<li><b>결혼 후</b>는 생활의 규칙에서 애정을 확인합니다. 밥·시간·약속이 곧 사랑의 언어가 됩니다.</li>'+
    '<li><b>오래 갈 조건</b>은 설렘이 아니라 서로의 리듬을 존중하는 것입니다. 같은 시간에 잠들지 못해도, 같은 시간에 대화할 수 있으면 됩니다.</li>'+
  '</ul>';
  return h;
}
function moneyExtra(R,c,input,name){
  var jae=c.gc['정재']+c.gc['편재'];
  var h='<h4 class="rb-h">돈과 사람의 관계</h4>';
  h+='<p class="rb-p">이 사주는 '+c.topGrp+'의 결로 돈을 움직여요. '+GROUP_MEAN[c.topGrp]+' 그래서 돈이 사람을 통해 들어오는 만큼 사람을 통해 새기도 합니다. 재성이 '+jae+'개인 이 사주는 '+(jae>=3?'돈의 문이 여러 개라 관리가 곧 실력입니다.':'돈의 문이 좁은 대신 깊어서 한 우물을 오래 파는 쪽이 남습니다.')+'</p>';
  h+='<p class="rb-p">특히 '+ (c.gc['겁재']>=1?'겁재가 '+c.gc['겁재']+'개 있어 사람과의 돈 거래에서 결정이 흐려집니다. 보증·동업·대여는 서류로 남기세요.':(c.gc['편재']>=1?'편재가 '+c.gc['편재']+'개 있어 수입이 늘어난 달에 지출도 함께 늘어납니다. 늘어난 금액의 절반을 먼저 떼어두세요.':'재성이 크지 않아 새는 곳이 뚜렷하지 않은 대신, 돈을 관리하는 시스템이 없으면 어디로 갔는지 모르는 달이 생깁니다.'))+'</p>';
  h+='<h4 class="rb-h">1년 안에 할 수 있는 재물 개운</h4>';
  h+='<ul class="rb-ul">'+
    '<li>수입의 10퍼센트를 <b>자동이체</b>로 떼어두기. 금액보다 자동이 중요합니다.</li>'+
    '<li>큰 지출 전 <b>하루</b> 두기. 이 사주는 마음이 앞서는 날 지출도 커집니다.</li>'+
    '<li>사람에게 쓰는 돈의 <b>월 한도</b> 정하기. 정이 앞서는 지점이 여기예요.</li>'+
  '</ul>';
  return h;
}
function healthExtra(R,c,input,name){
  var h='<h4 class="rb-h">병원을 미루는 습관</h4>';
  h+='<p class="rb-p">이 사주는 '+EL_DEEP[R.dayEl].part+' 쪽 신호를 참는 편이에요. 통증이 아니라 <b>피로</b>로 먼저 오기 때문에 “좀 쉬면 낫겠지” 하다가 오래 끌립니다. 3주 이상 같은 증상이 이어지면 그때는 참지 말고 확인하세요.</p>';
  h+='<p class="rb-p">그리고 이 사주는 <b>'+SEASON_RHYTHM[c.leastI][0]+'</b>에 유난히 무리하기 쉽습니다. 그 시기에 큰 일정을 몰아넣으면 다음 계절까지 컨디션이 끌려가요. 달력에 그 계절만 표시해두고, 그때는 약속을 절반으로 줄이세요.</p>';
  h+='<h4 class="rb-h">3개월 건강 루틴</h4>';
  h+='<ul class="rb-ul">'+
    '<li><b>1개월</b> — 잠드는 시간만 고정합니다. 다른 건 바꾸지 않아도 됩니다.</li>'+
    '<li><b>2개월</b> — '+EL_DEEP[R.dayEl].food+'을 한 끼에 하나씩. '+EL_DEEP[c.mostI].taste+'은 줄여보세요.</li>'+
    '<li><b>3개월</b> — '+EL_DEEP[c.yongEl].habit+'을 주 3회. 이 사주에 가장 필요한 기운을 채우는 습관이에요.</li>'+
  '</ul>';
  return h;
}
function gaewunExtra(R,c,input,name){
  var y=c.yongEl;
  var h='<h4 class="rb-h">개운을 3개월 안에 확인하는 법</h4>';
  h+='<p class="rb-p">개운은 기도나 부적이 아니라 <b>환경을 바꾸는 일</b>이에요. 이 사주에 필요한 '+elB(y)+'의 결을 세 달 동안 일상에 들이면, 잠의 질과 결정의 속도가 먼저 달라집니다. 그 두 가지가 바뀌면 돈과 사람의 흐름도 따라옵니다.</p>';
  h+='<ul class="rb-ul">'+
    '<li><b>1개월</b> — '+EL_DEEP[y].color+' 계열 소품 하나를 매일 보는 자리에. 지갑·다이어리·컵처럼 손이 자주 가는 것으로.</li>'+
    '<li><b>2개월</b> — '+EL_DEEP[y].dir+' 방향으로 책상이나 침대 머리를 옮겨보세요. '+EL_DEEP[y].space+'.</li>'+
    '<li><b>3개월</b> — '+EL_DEEP[y].habit+'을 일과에 넣고, '+EL_DEEP[y].food+'을 주 3회. 몸이 먼저 반응합니다.</li>'+
  '</ul>';
  return h;
}


function chMoneyGeneral(R,c,input,name){
  return secMoney(R,c,input,name)+moneyExtra(R,c,input,name);
}

function chCareerGeneral(R,c,input,name){
  var top=c.topGodInGrp;
  var guan=c.grp['관성'], sik=c.grp['식상'], jae=c.grp['재성'];
  var h='';
  h+='<p class="rb-p">직업운은 한 글자로 정해지지 않아요. <b>무엇을 만들 수 있는가</b>(식상), <b>누가 나를 알아보는가</b>(관성), <b>그 일이 돈이 되는가</b>(재성)를 함께 봅니다. '+name+' 님은 식상 <b>'+sik+'개</b> · 관성 <b>'+guan+'개</b> · 재성 <b>'+jae+'개</b>로 이 셋이 놓여 있어요.</p>';
  h+='<h4 class="rb-h">천직의 결</h4>';
  h+='<p class="rb-p">가장 두터운 <b>'+c.topGrp+'</b>과 가장 강한 '+elB(c.mostI)+' 기운을 겹쳐보면, 이 사주가 오래 버티는 일은 <b>'+WORK_BY_GRP[c.topGrp]+'</b> 쪽이에요. 세부 업종으로는 <b>'+CAREER[c.mostI].join(' · ')+'</b> 같은 자리가 잘 맞습니다.</p>';
  h+='<p class="rb-p">'+GOD_DEEP[top]+' 이 별이 중심이라, 일을 고를 때 <b>연봉보다 「내가 이 일에서 무엇을 쓰는가」</b>를 먼저 보세요. 이 사주는 쓰는 것이 분명할 때 오래 갑니다.</p>';

  h+='<h4 class="rb-h">성공하는 방식 — 밀어붙이기인가, 쌓기인가</h4>';
  if(guan>=3){
    h+='<p class="rb-p">관성이 두터워 <b>조직 안에서 자리를 올리는 방식</b>이 몸에 맞아요. 규칙과 절차가 나를 보호해주고, 직함이 붙을 때 힘이 실립니다. 다만 윗사람에게 서운한 일을 오래 안고 있으면 그게 곧 이직 충동이 되니, 감정은 그 주에 정리하세요.</p>';
  } else if(guan>=2){
    h+='<p class="rb-p">조직과 독립이 반반이에요. 한 곳에 소속되되 <b>내 전문 영역을 따로 가진 형태</b>가 가장 이상적입니다. 사내 전문가 트랙, 겸업, 프로젝트 리드처럼 「소속은 있지만 이름은 내 것」인 자리가 잘 맞아요.</p>';
  } else {
    h+='<p class="rb-p">관성이 얇아 <b>스스로 판을 만드는 쪽</b>이 잘 맞습니다. 누가 시켜주길 기다리는 자리에서는 힘이 안 나고, 내가 정한 일을 내 방식으로 밀 때 성과가 나요. 대신 마감과 보고를 스스로 만드는 장치가 필요합니다.</p>';
  }
  h+='<p class="rb-p">여기에 '+c.topGrp+'의 결이 더해져, 이 사람이 가장 잘 자라는 환경은 <b>'+ENV_BY_EL[R.dayEl]+'</b>이에요. 반대로 기준이 자꾸 바뀌고 공로가 흐려지는 자리는, 능력과 무관하게 기운을 많이 씁니다.</p>';

  h+='<h4 class="rb-h">인정받는 시기</h4>';
  var gy=seunYearsByGroup(R,'관성');
  if(gy.length){
    h+='<p class="rb-p">앞으로 5년 중 관성(자리·책임)이 세운으로 들어오는 해는 <b>'+gy.map(function(o){return o.y+'년('+o.g+')';}).join(', ')+'</b>이에요. 이 해에는 승진·발령·공식 계약처럼 <b>이름이 붙는 일</b>이 생기기 쉽습니다. 서류와 면접, 제안서는 이 흐름에 맞춰 준비하세요.</p>';
  } else {
    h+='<p class="rb-p">앞으로 5년에는 관성이 세운으로 직접 들어오지 않아요. 대신 <b>실력을 쌓아 이름을 만드는 시기</b>로 보면 됩니다. 자격·포트폴리오·기록처럼 나중에 증명이 되는 것들을 이 5년에 남겨두세요.</p>';
  }
  h+='<h4 class="rb-h">직업의 세 가지 시나리오</h4>';
  h+='<p class="rb-p">첫째, 지금 자리에서 <b>전문 영역을 하나 더 깊게</b> 파는 길. 이 사주는 '+c.topGrp+'의 결이 두터워 한 분야의 이름을 만드는 쪽이 안정적이에요. 둘째, 같은 일을 <b>다른 판</b>에서 하는 길. 업종은 같아도 조직의 성격이 바뀌면 기운이 살아납니다. 셋째, <b>내 일을 작게 여는</b> 길. 이 사주는 검증 가능한 크기로 시작할 때 오래 갑니다.</p>';
  h+='<p class="rb-p">세 길 중 무엇이 맞는지는 능력보다 <b>생활의 리듬</b>이 정해요. 아침형인지, 사람을 많이 만나는 일이 편한지, 결정을 혼자 내리는 것이 좋은지 — 이 세 가지를 먼저 확인하세요. '+ENV_BY_EL[R.dayEl]+' 쪽의 환경이 이 사주를 가장 편하게 합니다.</p>';
  h+='<div class="rb-key"><b>일의 방향 한 줄</b><span>'+name+' 님은 「'+GOD_KEY[top]+'」을 무기로, '+WORK_BY_GRP[c.topGrp].split(',')[0]+'에서 오래 갈 때 가장 멀리 갑니다.</span></div>';
  return h;
}

function chHealthGeneral(R,c,input,name){
  return secHealth(R,c,input,name)+healthExtra(R,c,input,name);
}

function chGuin(R,c,input,name){
  var y=c.yongEl, z=zodiacOfEl(y);
  var h='';
  h+='<p class="rb-p">귀인은 멀리 있는 사람이 아니라, <b>내 사주에 없는 기운을 가진 사람</b>이에요. '+name+' 님에게 필요한 기운은 '+elB(y)+'이고, 그 기운을 타고난 사람이 이 사주의 귀인이 됩니다.</p>';
  h+='<h4 class="rb-h">귀인의 오행과 띠</h4>';
  h+='<p class="rb-p">귀인의 결은 <b>'+EL_PERSON[y]+'</b>예요. '+EL_DEEP[y].over.split('.')[0]+'. 이런 사람은 내가 흥분했을 때 말을 낮춰주고, 내가 지쳤을 때 다음 순서를 조용히 정리해줍니다. 띠로 보면 <b>'+listKo(z)+'</b> 띠가 이 기운에 해당해요. 다만 띠보다 <b>그 사람이 어떤 방식으로 말하고 정리하는지</b>가 더 정확합니다.</p>';
  h+='<p class="rb-p">귀인의 나이대는 정해져 있지 않지만, 이 사주는 '+EL_KO[y]+'의 기운을 가진 사람에게 <b>먼저 다가가는 쪽</b>이 유리해요. 윗사람이라면 배움을 청하고, 또래라면 함께 배우는 자리를 만드세요.</p>';

  h+='<h4 class="rb-h">귀인을 만나는 자리</h4>';
  h+='<p class="rb-p">이 사주가 사람을 얻는 자리는 <b>'+ENV_BY_EL[y]+'</b>예요. '+EL_DEEP[y].dir+' 방향의 공간, '+EL_DEEP[y].season+'에 열리는 모임에서 인연이 시작되기 쉽습니다. 큰 행사보다 <b>여섯 명 이하의 작은 자리</b>에서 오래 남는 사람을 만나요.</p>';
  h+='<h4 class="rb-h">귀인을 알아보는 신호</h4>';
  h+='<ul class="rb-ul">'+
    '<li>내가 말을 꺼내기 전에 <b>내 상태를 먼저 알아채는 사람</b>. 이 사주는 설명을 잘 못 하니, 알아봐 주는 사람이 귀인입니다.</li>'+
    '<li>내 이야기를 들은 뒤 <b>구체적인 다음 행동을 하나 정해주는 사람</b>. 위로만 하는 사람보다 이 사람이 오래 남아요.</li>'+
    '<li>내가 잘났을 때보다 <b>내가 흔들릴 때 태도가 변하지 않는 사람</b>. 귀인은 좋은 날보다 나쁜 날에 드러납니다.</li>'+
  '</ul>';
  h+='<h4 class="rb-h">내가 누군가의 귀인이 되는 법</h4>';
  h+='<p class="rb-p">이 사주가 가진 넘치는 '+elB(c.mostI)+' 기운은 다른 사람에게는 귀한 재료예요. '+EL_DEEP[c.mostI].over.split('.')[0]+' 이 결을 필요한 사람에게 <b>조용히 빌려주는 것</b>이 이 사람의 귀인 노릇입니다. 대신 대가를 기대하면 관계가 상해요. 한 번 도운 일은 잊는 편이 오래갑니다.</p>';
  h+='<h4 class="rb-h">귀인과의 거리 조절</h4>';
  h+='<p class="rb-p">귀인은 가까이 붙는 사이라고 해서 좋은 것이 아니에요. 이 사주는 '+c.topGrp+'의 결이 두터워, 가까운 사이에서 서운함이 쌓이면 조용히 거리를 두는 쪽을 택합니다. 귀인에게도 같은 일이 생길 수 있으니 <b>한 달에 한 번은 고마움을 말로</b> 전하세요.</p>';
  h+='<p class="rb-p">그리고 이 사주는 도움을 청하는 데 시간이 걸립니다. 그래서 귀인이 “필요하면 말해”라고 해도 실제로는 말하지 않아요. 귀인을 오래 곁에 두는 방법은 <b>작은 부탁을 먼저 하는 것</b>입니다. 작은 부탁이 관계를 만들어 주고, 큰 도움은 그 뒤에 자연스럽게 옵니다.</p>';
  h+='<div class="rb-key"><b>귀인 한 줄</b><span>'+listKo(z)+' 띠, '+EL_KO[y]+'의 결을 가진 '+EL_PERSON[y]+'. 이 사람 곁에 있으면 내 결정이 빨라집니다.</span></div>';
  return h;
}

function chGaewun(R,c,input,name){
  return secOhaeng(R,c,input,name)+gaewunExtra(R,c,input,name);
}

function chYearMonths(R,c,input,name){
  var bd=bestDaeun(R,c), bn=R.daeun[bd.i], bg=tenGod(R.dStem,bn.idx%10);
  var h='';
  h+='<p class="rb-p">한 해의 운은 <b>대운이라는 큰 방향</b> 위에 얹힌 날씨예요. 같은 대운 안에서도 달마다 강조되는 기운이 달라서, 무엇을 시작하고 무엇을 미룰지가 정해집니다. 아래 달력은 이번 달부터 열두 달의 월주를 '+name+' 님의 일간과 견준 것입니다.</p>';
  h+=monthFlow(R,c,'general',12,'');
  h+='<h4 class="rb-h">대운과 세운을 함께 읽는 법</h4>';
  h+='<p class="rb-p">대운이 큰 방향이라면 세운은 그해의 날씨예요. 같은 대운 안에서도 해마다 강조되는 것이 달라서, 대운이 좋아도 세운이 부딪히는 해에는 속도를 줄여야 합니다. 반대로 대운이 무거워도 세운이 합으로 들어오는 해에는 사람을 통해 숨통이 트여요.</p>';
  h+='<p class="rb-p">그래서 이 사주는 <b>'+DAEUN_KEY[tenGod(R.dStem,R.daeun[R.curDaeun].idx%10)]+'</b>의 10년 안에서, 해마다 다른 날씨를 읽으며 살아야 합니다. 아래 12개월 달력에서 그 날씨를 확인하고, 큰 결정은 두 해의 흐름이 겹치는 달에 두세요.</p>';
  h+='<h4 class="rb-h">그 위에 놓인 10년</h4>';
  h+='<p class="rb-p">열두 달의 흐름은 결국 <b>지금 대운</b>의 방향으로 모입니다. 지금은 '+DAEUN_KEY[tenGod(R.dStem,R.daeun[R.curDaeun].idx%10)]+'의 시기이고, 이 사주의 힘이 가장 잘 실리는 때는 <b>'+bn.from+'~'+bn.to+'세('+bg+')</b>예요.</p>';
  h+='<p class="rb-p">그 10년을 준비하는 방법은 지금 하는 일의 <b>기록을 남기는 것</b>입니다. 이 사주는 '+c.topGrp+'의 결이 두터워, 말보다 쌓인 결과물로 평가받을 때 크게 도약합니다. 올해와 내년에 남긴 기록이 황금기의 첫 재료가 됩니다.</p>';
  h+='<div class="rb-key"><b>12개월 사용법</b><span>재성이 오는 달에는 돈과 계약을, 관성이 오는 달에는 자리와 서류를, 인성이 오는 달에는 배움과 회복을 배치하세요. 세 가지를 같은 달에 몰아넣으면 어느 것도 남지 않습니다.</span></div>';
  return h;
}

