function partnerChart(input){
  var p=input.ctx&&input.ctx.partner;
  if(!p||!p.y) return null;
  try{
    var Rp=computeSaju({y:p.y,m:p.m,d:p.d,hasTime:!!p.hasTime,hourIndex:p.hourIndex||0,gender:p.gender||'m',tsoff:p.tsoff||0,regionName:p.regionName||''});
    return {R:Rp,c:chartCtx(Rp),y:p.y,m:p.m,d:p.d};
  }catch(e){ return null; }
}
function loveSignal(R,c){
  var out=[];
  if(c.grp['식상']>=3) out.push('좋아하면 티가 먼저 나는 편이에요. 말투가 가벼워지고 연락 빈도가 갑자기 올라갑니다.');
  else if(c.grp['인성']>=3) out.push('좋아할수록 말수가 줄고, 대신 상대의 말을 오래 기억해요. 표현이 줄어드는 게 이 사주의 고백입니다.');
  else if(c.grp['관성']>=3) out.push('좋아하면 챙기기 시작해요. 일정을 물어보고, 밥을 챙기고, 조용히 뒤에서 정리해줍니다.');
  else if(c.grp['재성']>=3) out.push('좋아하면 만남을 구체적으로 잡아요. 연락보다 실제 약속으로 마음을 증명하는 편입니다.');
  else out.push('좋아해도 한참 뒤에야 인정하는 편이에요. 마음이 생긴 초기에는 오히려 무관심해 보입니다.');
  return out[0];
}
function chLoveNature(R,c,input,name){
  var h='';
  h+='<p class="rb-p">'+name+' 님은 <b>'+STEM_HAN[R.dStem]+BR_HAN[R.dBranch]+'일주</b>, '+ILJU[R.dIdx][0]+'의 결을 가진 사람이에요. 그 사주가 사람을 사랑할 때는 어떤 모습이 되는지부터 펼쳐볼게요.</p>';
  h+='<p class="rb-p">'+DM_DEEP[R.dStem].out+' 겉으로 보이는 연애 태도는 여기서 출발합니다. 그래서 처음 만난 사람은 '+name+' 님을 “차분하다” “쉽게 마음을 안 준다”고 기억해요.</p>';
  h+='<h4 class="rb-h">당신의 사랑의 언어</h4>';
  h+='<p class="rb-p">사랑을 느끼는 방식은 일간보다 <b>필요한 기운</b>에서 더 선명해요. 이 사주의 사랑의 언어는 아래와 같습니다.</p>';
  h+='<p class="rb-p">'+LOVE_LANG[R.dayEl]+'</p>';
  h+='<p class="rb-p">그래서 이 사주는 상대가 <b>같은 방식으로 사랑을 표현하지 않으면</b> 마음을 닫는 쪽으로 결론을 내리기 쉬워요. “저 사람은 나를 좋아하지 않는가”가 아니라 “저 사람은 다르게 표현하는구나”로 읽어보면 관계가 한 번 살아납니다.</p>';
  h+='<h4 class="rb-h">좋아할 때 드러나는 신호</h4>';
  h+='<p class="rb-p">'+loveSignal(R,c)+' 사주에서 <b>'+c.topGrp+'</b>이 두터운 만큼, 이 사람의 호감은 '+GOD_KEY[c.topGodInGrp]+'의 방식으로 표현됩니다. '+GROUP_MEAN[c.topGrp]+'</p>';
  h+='<h4 class="rb-h">사랑이 흔들리는 지점</h4>';
  h+='<p class="rb-p">'+LOVE_SHADOW[R.dayEl]+'</p>';
  h+='<p class="rb-p">'+STRENGTH_TXT[R.strength].adv+'</p>';
  h+='<h4 class="rb-h">연애의 속도</h4>';
  h+='<p class="rb-p">이 사주는 '+(R.strength==='강'?'마음을 정하면 빠르게 움직이는 편이에요. 다만 상대가 같은 속도가 아닐 때 서운함이 커집니다.':(R.strength==='약'?'상대의 신호를 오래 확인한 뒤 움직여요. 그래서 확신이 없으면 시작 자체를 미룹니다.':'상황을 보며 속도를 조절하는 편이에요. 상대에 따라 다르게 보이지만, 그만큼 유연합니다.'))+'</p>';
  h+='<h4 class="rb-h">겉과 속의 온도차</h4>';
  h+='<p class="rb-p">'+DM_DEEP[R.dStem].in+' 그래서 이 사주는 마음이 커질수록 표현이 줄어들어요. 상대는 그 조용함을 “관심이 식었다”로 읽지만, 실제로는 <b>더 깊이 들어간 상태</b>입니다. 이 차이를 설명하지 않으면 같은 오해가 반복돼요.</p>';
  h+='<p class="rb-p">이 사주가 사랑에서 가장 먼저 지치는 순간은 <b>'+DM_DEEP[R.dStem].drain.split('.')[0]+'</b>일 때예요. '+DM_DEEP[R.dStem].drain+' 이 신호가 보이면 관계를 정리하기 전에, 하루만 시간을 두고 “지금 내가 지친 건지, 상대가 싫어진 건지”를 나눠보세요.</p>';
  h+='<h4 class="rb-h">사랑을 오래 유지하는 조건</h4>';
  h+='<ul class="rb-ul">'+
    '<li><b>설명하는 연습</b> — 마음이 큰 날일수록 한 문장이라도 말로 꺼내세요. 이 사주는 표현이 줄면 상대가 떠납니다.</li>'+
    '<li><b>같은 리듬</b> — 잠드는 시간과 연락하는 시간이 비슷한 사람과 오래 갑니다. 이 사주는 리듬이 어긋나면 애정이 있어도 피곤해져요.</li>'+
    '<li><b>혼자 있는 시간</b> — '+EL_DEEP[c.yongEl].habit+'처럼 자기만의 회복 시간을 관계 안에서도 보장받아야 합니다.</li>'+
  '</ul>';
  h+='<div class="rb-key"><b>연애 한 줄</b><span>사랑의 언어는 「'+LOVE_LANG[R.dayEl].split('.')[0]+'」. 상대가 그 언어를 모를 때는 내가 먼저 알려주세요.</span></div>';
  return h;
}

function chLoveType(R,c,input,name){
  var de=R.dayEl, se=BR_EL[R.dBranch];
  var pull='';
  if(de===se) pull='나와 결이 같은 사람을 만나요. 친구처럼 편한 사이에서 애정이 자라요. 처음에는 연인보다 동료 같은 느낌으로 시작합니다.';
  else if(generates(se,de)) pull='나를 돌봐주는 사람에게 끌려요. 내가 지칠 때 기대어 앉을 수 있는 사람이에요. 다만 그 돌봄이 당연해지면 이 사주는 고마움을 표현하지 않게 됩니다.';
  else if(generates(de,se)) pull='내가 챙겨주고 싶은 사람에게 마음이 가요. 돌볼수록 애정이 깊어지는 편이에요. 다만 상대가 달라지면 마음도 빨리 식습니다.';
  else if(controls(se,de)) pull='나를 끌어당기고 이끄는 사람에게 끌려요. 긴장감이 곧 설렘이 되는 관계예요. 다만 오래가려면 긴장을 풀 시간을 따로 만들어야 합니다.';
  else pull='내가 아끼고 지켜주고 싶은 사람과 인연이 깊어요. 다만 내가 다 해주려다 지치지 않도록, 초반에 역할을 나눠두세요.';
  var h='';
  h+='<p class="rb-p">끌리는 사람과 잘 맞는 사람은 다릅니다. 앞의 것은 <b>일지 '+brB(R.dBranch)+'</b>가, 뒤의 것은 <b>필요한 기운 '+eko(c.yongEl)+'</b>이 알려줘요.</p>';
  h+='<h4 class="rb-h">내가 끌리는 사람</h4>';
  h+='<p class="rb-p">'+pull+'</p>';
  h+='<p class="rb-p">이 사주가 눈여겨보는 사람은 <b>'+LOVE_ATTRACT[de]+'</b></p>';
  h+='<h4 class="rb-h">실제로 오래 가는 사람</h4>';
  h+='<p class="rb-p">'+LOVE_FIT[c.yongEl]+'</p>';
  h+='<p class="rb-p">명리에서 보는 궁합은 “비슷한 사람”이 아니라 <b>내게 없는 것을 가진 사람</b>이에요. 이 사주에는 '+elB(c.leastI)+' 기운이 가장 적어서, 그 기운을 가진 사람 앞에서 내가 편해집니다. 화려함이나 공통 취미는 시작을 만들 뿐, 오래 가는 힘은 이 보완에서 나옵니다.</p>';
  h+='<h4 class="rb-h">끌림과 궁합 사이의 틈</h4>';
  h+='<p class="rb-p">이 사주가 반복해서 만나는 유형은 <b>'+LOVE_ATTRACT[de].split('.')[0]+'</b> 쪽입니다. 그 사람에게는 설렘이 크지만, 생활에서는 ‘<b>'+EL_KO[c.leastI]+'</b>’이 부족해 피곤해져요. 반대로 처음엔 밋밋하게 느껴진 <b>'+EL_PERSON[c.yongEl]+'</b>에게 오래 머물게 됩니다. 두 사람을 비교할 때 설렘의 크기보다 <b>대화가 끝난 뒤의 편안함</b>을 기준으로 삼아보세요.</p>';
  var star=(input.gender==='f')?'관성':'재성';
  var starCnt=c.grp[star];
  h+='<h4 class="rb-h">배우자성으로 보는 인연의 결</h4>';
  h+='<p class="rb-p">'+(input.gender==='f'?'여성 사주에서는 관성(官星)':'남성 사주에서는 재성(財星)')+'이 배우자를 보는 창이에요. 이 사주는 '+star+'이 <b>'+starCnt+'개</b>로 '+(starCnt>=3?'넉넉한 편이라 인연이 끊이지 않고 들어옵니다. 다만 고르는 기준이 없으면 좋은 인연도 흘려보내요.':(starCnt>=1?'적지 않게 놓여 있어, 한 번 마음을 정하면 오래갑니다.':'얇은 편이라 인연이 스스로 오기보다 내가 나가서 만나는 쪽이 맞습니다.'))+'</p>';
  h+='<h4 class="rb-h">세 유형, 만나면 어떻게 되는가</h4>';
  h+='<p class="rb-p"><b>나와 같은 사람</b> — 편하고 빠르게 친해지지만, 같은 약점이 함께 커집니다. 둘 다 지친 날에는 아무도 밥을 챙기지 않는 관계예요. 오래 가려면 한 사람이 규칙을 만들어야 합니다.</p>';
  h+='<p class="rb-p"><b>나를 살리는 사람</b> — 처음엔 밋밋하게 느껴질 수 있어요. 그런데 이 사람 곁에서는 잠이 잘 오고, 결정이 빨라집니다. 이 사주에게 오래 가는 인연은 대개 이쪽이에요.</p>';
  h+='<p class="rb-p"><b>내가 살리는 사람</b> — 설렘이 크고 관계가 뜨겁습니다. 다만 이 사주가 계속 챙기는 쪽이 되면 1~2년 뒤에 조용히 지칩니다. 초반에 역할을 나눠두면 오래 갑니다.</p>';
  h+='<h4 class="rb-h">유형을 판별하는 세 질문</h4>';
  h+='<ul class="rb-ul">'+
    '<li>이 사람과 있은 뒤 <b>기운이 남는가, 빠지는가</b>.</li>'+
    '<li>내가 말하지 않아도 <b>내 상태를 알아채는가</b>.</li>'+
    '<li>내가 잘못했을 때 <b>사람을 미워하지 않고 일을 짚는가</b>.</li>'+
  '</ul>';
  h+='<div class="rb-key"><b>유형 한 줄</b><span>끌림은 '+EL_KO[BR_EL[R.dBranch]]+' 쪽, 오래감은 '+EL_KO[c.yongEl]+' 쪽. 결정할 때는 두 번째 사람을 떠올려 보세요.</span></div>';
  return h;
}

function chPartnerMind(R,c,input,name){
  var pc=partnerChart(input), h='';
  if(!pc){
    h+='<p class="rb-p">상대의 속마음은 <b>상대의 여덟 글자</b>가 있어야 정확히 읽을 수 있어요. 지금은 상대의 생년월일이 비어 있어서, 이 사주가 사람을 대하는 방식과 지금 흐르는 인연의 결로 대신 읽어볼게요.</p>';
    h+='<h4 class="rb-h">당신이 사람을 대하는 온도</h4>';
    h+='<p class="rb-p">'+DM_DEEP[R.dStem].in+' 그래서 상대는 '+name+' 님의 마음을 <b>실제보다 차갑게</b> 읽을 수 있어요. 마음이 클수록 표현이 줄어드는 게 이 사주의 습관입니다.</p>';
    h+='<p class="rb-p">지금 인연의 자리는 일지 '+brB(R.dBranch)+'가 보여줘요. '+SPOUSE[R.dBranch]+' 쪽의 사람이 마음에 걸린다면, 그건 우연이 아니라 이 사주가 오래 머무는 결입니다.</p>';
    h+='<h4 class="rb-h">지금 상대가 느끼는 것</h4>';
    h+='<p class="rb-p">올해 세운은 <b>'+STEM_HAN[R.seun[0].idx%10]+BR_HAN[R.seun[0].idx%12]+'</b>으로, '+name+' 님에게 <b>'+tenGod(R.dStem,R.seun[0].idx%10)+'</b>의 기운이 들어와 있어요. '+SEUN_DEEP[tenGod(R.dStem,R.seun[0].idx%10)]+' 이 기운은 사람을 대하는 태도에도 그대로 묻어나서, 상대는 올해의 '+name+' 님을 평소와 다르게 느낍니다.</p>';
    h+='<p class="rb-p">상대의 생년월일을 함께 넣으면 두 사람의 일간·일지가 만나는 자리, 상대가 지금 무엇에 마음이 가 있는지까지 짚어드릴 수 있어요. 위의 「함께 볼 사람」에 상대의 생년월일을 적고 다시 열어보세요.</p>';
    h+='<h4 class="rb-h">상대의 속마음을 읽는 세 가지 신호</h4>';
    h+='<ul class="rb-ul">'+
      '<li><b>연락의 속도</b> — 이 사주는 답장 시간으로 마음을 재지만, 상대는 그렇지 않을 수 있어요. 답이 늦어도 <b>내용이 길거나 질문이 있으면</b> 관심이 있는 쪽입니다.</li>'+
      '<li><b>만남을 잡는 방식</b> — “언제 시간 돼?”보다 “이번 주 목요일 어때?”가 나오면 상대는 이미 마음을 정한 쪽이에요.</li>'+
      '<li><b>말의 기억</b> — 지난번에 내가 한 사소한 말을 다시 꺼내면, 상대는 나를 기억하고 있는 겁니다.</li>'+
    '</ul>';
    h+='<p class="rb-p">이 사주는 신호를 <b>과하게 읽는</b> 편이라, 없는 의미를 찾다가 스스로 지칩니다. 신호가 애매하면 해석을 늘리지 말고 한 번 물어보세요. “요즘 우리 어떻게 지내는 것 같아?” 한 문장이면 충분합니다.</p>';
    h+='<h4 class="rb-h">지금 내가 흔들리는 이유</h4>';
    h+='<p class="rb-p">올해 세운 <b>'+tenGod(R.dStem,R.seun[0].idx%10)+'</b>은 '+SEUN_DEEP[tenGod(R.dStem,R.seun[0].idx%10)]+' 이 기운이 사람을 대하는 태도에도 묻어나서, 평소보다 확인하고 싶은 마음이 커집니다. 그 마음은 상대의 문제가 아니라 <b>내 계절의 문제</b>예요.</p>';
    h+='<div class="rb-key"><b>지금 할 수 있는 것</b><span>완벽한 문장을 준비하기보다, 상대가 최근에 말한 것 하나를 기억했다가 그걸로 대화를 여세요. 이 사주의 강점은 기억력입니다.</span></div>';
    return h;
  }
  var pR=pc.R, pcp=pc.c;
  var me=R.dayEl, pa=pR.dayEl;
  var relTxt='';
  if(me===pa) relTxt='두 사람의 일간이 같은 오행이에요. 설명하지 않아도 통하는 부분이 많고, 말이 짧아도 이해가 됩니다. 다만 같은 약점도 함께 커져서, 둘 다 지친 날에는 서로를 채워주지 못합니다.';
  else if(generates(me,pa)) relTxt='내 기운이 상대를 살리는 구조예요. 내가 챙기고 돌보는 만큼 관계가 깊어집니다. 다만 한쪽으로만 기울면 내가 지칩니다.';
  else if(generates(pa,me)) relTxt='상대의 기운이 나를 살리는 구조예요. 내가 지칠 때 기대어 앉을 자리가 있는 관계라 회복이 빠릅니다.';
  else if(controls(me,pa)) relTxt='내 기운이 상대를 누르는 구조예요. 내가 주도권을 쥐기 쉽지만, 상대는 조용히 지칠 수 있습니다.';
  else relTxt='상대의 기운이 나를 누르는 구조예요. 끌림은 강하지만 내가 늘 맞추는 쪽이 되기 쉬워요.';
  var br=branchRel(R.dBranch,pR.dBranch);
  var pIdx=mod((new Date()).getFullYear()-4,60);
  var pg=tenGod(pR.dStem,pIdx%10), pgrp=GOD_GROUP[pg];
  h+='<p class="rb-p">상대의 일주는 <b>'+STEM_HAN[pR.dStem]+BR_HAN[pR.dBranch]+'</b>, 일간은 '+stemB(pR.dStem)+'이에요. 상대의 결은 '+ILJU[pR.dIdx][0]+' — '+ILJU[pR.dIdx][1]+'</p>';
  h+='<h4 class="rb-h">두 사람의 기운이 만나는 자리</h4>';
  h+='<p class="rb-p">'+relTxt+'</p>';
  h+='<p class="rb-p">일지끼리는 '+brB(R.dBranch)+'와 '+brB(pR.dBranch)+'로 <b>'+br.k+'</b>의 관계예요. '+br.t+'</p>';
  h+='<h4 class="rb-h">상대의 속마음 — 지금 무엇을 보고 있는가</h4>';
  h+='<p class="rb-p">상대의 사주에서 가장 두터운 기운은 <b>'+pcp.topGrp+'</b>이고, 중심 별은 <b>'+pcp.topGodInGrp+'</b>이에요. '+GOD_DEEP[pcp.topGodInGrp]+' 그래서 상대는 '+name+' 님의 다정함을 <b>'+GOD_KEY[pcp.topGodInGrp]+'</b>의 방식으로 받아들입니다.</p>';
  h+='<p class="rb-p">올해 상대의 세운은 <b>'+STEM_HAN[pIdx%10]+BR_HAN[pIdx%12]+'('+pg+')</b>이에요. '+PARTNER_MIND[pgrp]+'</p>';
  h+='<p class="rb-p">상대의 일지 '+brB(pR.dBranch)+'는 '+SPOUSE[pR.dBranch]+' 쪽을 오래 붙잡는 자리예요. 상대가 지금 '+name+' 님을 대하는 태도가 평소와 다르다면, 마음이 식은 것이 아니라 <b>'+(pgrp==='관성'||pgrp==='인성'?'자기 안에서 정리하는 중':'자기 일에 몰두하는 중')+'</b>일 가능성이 큽니다.</p>';
  h+='<h4 class="rb-h">상대에게 통하는 말투</h4>';
  h+='<p class="rb-p">상대의 일간이 '+eko(pa)+'이라, '+EL_DEEP[pa].over.split('.')[0]+' 이 결에 맞는 대화가 필요해요. '+EL_DEEP[pa].under.split('.')[0]+' 그래서 '+name+' 님이 서두르면 상대는 이유를 말하지 않고 물러납니다. 결론을 재촉하는 문장 대신 <b>“요즘 어떤 게 제일 신경 쓰여?”</b>처럼 상대가 자기 이야기를 꺼낼 수 있는 질문이 잘 통해요.</p>';
  h+='<h4 class="rb-h">상대가 좋아하는 표현</h4>';
  h+='<p class="rb-p">이 사주는 내 방식으로 다정하게 대하지만, 상대는 다른 언어로 사랑을 확인할 수 있어요. 상대의 일간이 '+eko(pa)+'이라 '+LOVE_LANG[pa]+' 그래서 '+name+' 님이 아무리 마음이 커도, 상대의 언어로 한 번 표현하지 않으면 전달되지 않습니다.</p>';
  h+='<p class="rb-p">상대에게 필요한 기운은 '+elB(pcp.yongEl)+'이에요. '+EL_PERSON[pcp.yongEl]+' 쪽의 사람에게 마음이 열리는 상대이니, '+name+' 님이 그 결로 다가가면 훨씬 잘 통해요. 화려한 이벤트보다 <b>상대의 하루를 기억하는 말</b>이 오래 남습니다.</p>';
  h+='<div class="rb-key"><b>상대 마음 한 줄</b><span>'+name+' 님은 '+GOD_KEY[c.topGodInGrp]+'으로 다가가고, 상대는 '+GOD_KEY[pcp.topGodInGrp]+'으로 받습니다. 이 차이를 알면 오해의 절반이 사라집니다.</span></div>';
  return h;
}

function sseomScore(R,c,input){
  var s=48, notes=[];
  var pc=partnerChart(input);
  if(pc){
    var pa=pc.R.dayEl, me=R.dayEl;
    if(me===pa){ s+=8; notes.push('일간이 같아 통하는 부분이 많아요'); }
    else if(generates(pa,me)){ s+=12; notes.push('상대의 기운이 나를 살려줘요'); }
    else if(generates(me,pa)){ s+=9; notes.push('내가 상대를 살리는 구조예요'); }
    else if(controls(me,pa)||controls(pa,me)){ s+=2; notes.push('서로 미는 힘이 있어 조율이 필요해요'); }
    var br=branchRel(R.dBranch,pc.R.dBranch);
    s+=br.s; notes.push('일지가 '+br.k+'의 관계예요');
    for(var i=0;i<5;i++){
      if(pc.R.count[i]===0&&R.count[i]>=2) s+=3;
      if(R.count[i]===0&&pc.R.count[i]>=2) s+=3;
    }
  } else {
    var st=c.grp['관성']+c.grp['재성'];
    s+=Math.min(12,st*3);
    notes.push('상대의 글자 없이 내 사주만으로 계산했어요');
  }
  var yg=tenGod(R.dStem,R.seun[0].idx%10), ygrp=GOD_GROUP[yg];
  if(ygrp==='관성'||ygrp==='재성'){ s+=7; notes.push('올해 세운이 인연을 밀어주고 있어요'); }
  if(ygrp==='인성'){ s-=4; notes.push('올해는 생각이 길어져 연락이 느려지기 쉬워요'); }
  s=Math.max(35,Math.min(94,Math.round(s)));
  return {s:s,notes:notes};
}
function chSseomTiming(R,c,input,name){
  var sc=sseomScore(R,c,input), pc=partnerChart(input);
  var band=sc.s>=80?'지금 밀어도 되는 흐름':(sc.s>=65?'한 번 더 확인하고 움직일 흐름':(sc.s>=50?'기다림이 필요한 흐름':'천천히 거리를 두고 볼 흐름'));
  var h='';
  h+='<p class="rb-p">썸과 재회는 마음의 문제이면서 <b>타이밍의 문제</b>예요. 두 사람의 글자와 지금 흐르는 세운을 겹쳐, 지금 움직여도 되는지부터 볼게요.</p>';
  h+='<div class="rb-special"><div class="sh"><i>時</i>지금 이 인연의 온도</div>';
  h+='<div class="score"><div class="num">'+sc.s+'<small>점</small></div><div class="mt"><div class="bar"><i style="width:'+sc.s+'%"></i></div><span>명리 참고 지수 · '+band+'</span></div></div>';
  h+='<p>이 점수는 '+sc.notes.join(', ')+'는 점을 반영했어요. 높고 낮음보다 <b>어느 쪽으로 움직이면 되는지</b>를 보세요.</p>';
  h+='<p class="disc-sm">상대의 시간(시주)과 실제 관계의 맥락은 반영되지 않은 참고값입니다.</p></div>';
  h+='<h4 class="rb-h">연락 타이밍 — 이 사주에 맞는 방식</h4>';
  if(c.grp['인성']>=3){
    h+='<p class="rb-p">이 사주는 연락을 <b>준비하는 데 시간이 걸리는 편</b>이에요. 그래서 “언제 보낼까”를 오래 재다가 때를 놓칩니다. 규칙을 하나 정하세요 — <b>마음이 생긴 날로부터 사흘 안에 한 번</b>. 문장은 길게 쓰지 말고, 상대가 답하기 쉬운 질문 하나로 끝내세요.</p>';
  } else if(c.grp['식상']>=3){
    h+='<p class="rb-p">이 사주는 연락이 빠른 대신 <b>말이 앞서는</b> 편이에요. 보내기 전에 한 번 지우고 다시 쓰면 관계가 오래 갑니다. 특히 밤 11시 이후의 긴 메시지는 다음 날 아침에 보내세요. 같은 내용도 결과가 달라집니다.</p>';
  } else if(c.grp['관성']>=3){
    h+='<p class="rb-p">이 사주는 연락을 <b>관계의 확인</b>으로 씁니다. 그래서 “우리 무슨 사이야”가 먼저 나가기 쉬워요. 지금은 그 질문을 미루고, 상대의 하루를 묻는 연락을 세 번 보낸 뒤에 물어보세요. 순서를 바꾸는 것만으로 답이 달라집니다.</p>';
  } else {
    h+='<p class="rb-p">이 사주는 연락보다 <b>만남으로 확인</b>하는 편이에요. 문자를 오래 주고받기보다 구체적인 약속을 하나 잡는 쪽이 잘 맞습니다. 날짜와 장소를 정해 보내면 상대도 답하기 쉬워요.</p>';
  }
  h+='<h4 class="rb-h">재회라면 — 마음보다 조건을 먼저 보세요</h4>';
  if(pc){
    var br=branchRel(R.dBranch,pc.R.dBranch);
    h+='<p class="rb-p">두 사람의 일지가 <b>'+br.k+'</b>로 묶여 있어요. '+br.t+'</p>';
  }
  h+='<p class="rb-p">재회는 감정이 남아 있는지보다 <b>헤어진 이유가 바뀌었는지</b>로 결정됩니다. 이 사주는 그리움이 커지면 이유를 잊어버리는 편이라, 다시 연락하기 전에 종이에 “그때 우리가 반복해서 부딪힌 것”을 세 줄로 적어보세요. 그중 두 줄이 그대로라면, 지금의 재회는 같은 결말을 한 번 더 겪는 일이 됩니다.</p>';
  h+='<ul class="rb-ul">'+
    '<li><b>1단계</b> — 짧은 안부 하나. 용건을 만들지 말고 상대의 근황만 묻습니다.</li>'+
    '<li><b>2단계</b> — 상대가 답하면 그 안에서 <b>한 번만</b> 더 이어가고 멈춥니다. 여기서 길게 가면 부담이 됩니다.</li>'+
    '<li><b>3단계</b> — 만남은 상대가 먼저 꺼낼 때 잡습니다. 이 사주가 먼저 잡으면 관계의 온도가 다시 내 쪽으로 쏠려요.</li>'+
  '</ul>';
  h+='<h4 class="rb-h">이번 주 연락 타이밍</h4>';
  h+='<p class="rb-p">이 사주의 일지 '+brB(R.dBranch)+'와 요일의 일진을 견주면, 연락이 잘 통하는 날과 피해야 할 날이 갈립니다.</p>';
  h+='<ul class="rb-ul">';
  var wd=['일','월','화','수','목','금','토'];
  for(var di=0;di<7;di++){
    var dd=new Date(); dd.setDate(dd.getDate()+di);
    var tIdx2=mod(10+(jdn(dd.getFullYear(),dd.getMonth()+1,dd.getDate())-jdn(1900,1,1)),60);
    var relDay=branchRel(R.dBranch,tIdx2%12);
    var mark=(relDay.k==='육합'||relDay.k==='삼합')?'<b>연락하기 좋은 날</b>':(relDay.k==='충'?'<b>피하는 날</b>':(relDay.k==='원진'?'서운함이 커지는 날':'무난한 날'));
    h+='<li>'+(dd.getMonth()+1)+'월 '+dd.getDate()+'일('+wd[dd.getDay()]+') — '+mark+'. '+ (relDay.k==='충'?'중요한 말은 미루고 짧은 안부만.':(relDay.k==='육합'||relDay.k==='삼합'?'먼저 연락하면 답이 잘 옵니다.':'길게 쓰지 말고 한 문장으로.'))+'</li>';
  }
  h+='</ul>';
  h+='<div class="rb-key"><b>타이밍 한 줄</b><span>지금은 '+band+'입니다. '+sc.s+'점이라는 숫자보다, 상대가 답을 했을 때 내가 <b>한 번만 더</b> 이어갈 수 있는지로 판단하세요.</span></div>';
  return h;
}

function chLoveConflict(R,c,input,name){
  var pc=partnerChart(input);
  var h='';
  h+='<p class="rb-p">이 사주가 사랑에서 부딪히는 지점은 성격이 나빠서가 아니라, <b>감정이 올라올 때 쓰는 방식</b>이 상대와 다르기 때문이에요.</p>';
  h+='<h4 class="rb-h">반복되는 충돌 장면</h4>';
  h+='<p class="rb-p">'+CONFLICT_BY_EL[R.dayEl]+'</p>';
  if(pc){
    var br=branchRel(R.dBranch,pc.R.dBranch);
    h+='<p class="rb-p">두 사람의 일지는 <b>'+br.k+'</b>예요. '+br.t+' 그래서 갈등이 생기면 감정의 세기가 아니라 <b>생활의 리듬</b>에서 먼저 어긋납니다. 잠드는 시간, 연락하는 시간, 주말을 보내는 방식 — 이 세 가지를 먼저 맞춰보세요.</p>';
    var pGrp=pc.c.topGrp;
    if(pGrp===c.topGrp) h+='<p class="rb-p">두 사람 모두 <b>'+pGrp+'</b>의 결이 두터워요. 그래서 같은 방식으로 화를 내고 같은 방식으로 닫힙니다. 한 사람이 먼저 말을 꺼내지 않으면 둘 다 끝까지 기다리는 구조예요. 이 사주가 먼저 <b>“지금 나 화난 게 아니라 서운해”</b>라고 말하는 것만으로 판이 바뀝니다.</p>';
    else h+='<p class="rb-p">상대는 <b>'+pGrp+'</b>의 결로 반응해요. '+GROUP_MEAN[pGrp]+' 나는 '+c.topGrp+'의 방식으로 말하니, 같은 사건을 다르게 기억합니다. 싸운 뒤에는 “무슨 일이 있었는지”보다 <b>“그때 뭐가 제일 서운했는지”</b>를 물어보세요.</p>';
  } else {
    h+='<p class="rb-p">상대의 생년월일을 넣으면 두 사람이 어디서 부딪히는지 더 정확히 짚을 수 있어요. 지금은 이 사주가 혼자 만들기 쉬운 갈등의 모양을 먼저 보여드릴게요.</p>';
  }
  h+='<h4 class="rb-h">화해의 순서</h4>';
  h+='<ul class="rb-ul">'+
    '<li><b>첫째, 장면을 말하지 말고 감정을 말하세요.</b> “네가 그때 그랬잖아” 대신 “그때 나는 혼자 남은 것 같았어”. 이 사주는 사실은 정확한데 감정을 빼고 말해서 상대가 변명으로 듣습니다.</li>'+
    '<li><b>둘째, 상대의 말을 한 문장으로 되돌려주세요.</b> “그래서 네 말은 ○○였다는 거지?” 이것만 해도 싸움의 절반이 풀립니다.</li>'+
    '<li><b>셋째, 다음에 어떻게 할지를 하나만 정하세요.</b> 결론이 여러 개면 지켜지지 않습니다. 하나만 정하고 그 하나를 지키는 게 이 사주에 맞는 화해법이에요.</li>'+
  '</ul>';
  h+='<h4 class="rb-h">건드리면 안 되는 선</h4>';
  h+='<p class="rb-p">'+name+' 님에게는 <b>'+GOD_KEY[c.topGodInGrp]+'</b>이 자존심의 핵심이에요. 이 부분을 무시당하면 사과를 받아도 마음이 돌아오지 않습니다. 반대로 상대도 자기 방식의 자존심이 있어요. 싸울 때 그 부분을 건드리지 않는 것만으로 관계의 수명이 크게 늘어납니다.</p>';
  h+='<h4 class="rb-h">갈등이 커지는 말 세 가지</h4>';
  h+='<ul class="rb-ul">'+
    '<li>“너는 항상 그래.” — 이 사주가 가장 자주 쓰는 말이에요. 한 번의 일을 <b>성격</b>으로 확대하면 상대는 변명만 하게 됩니다.</li>'+
    '<li>“됐어, 내가 할게.” — 도움을 거두는 말은 벌보다 오래 남습니다. 이 사주는 서운함이 쌓이면 이 말부터 나와요.</li>'+
    '<li>“그건 네가 알아서 해.” — 책임을 넘기는 순간 상대는 관계를 정리할 준비를 합니다.</li>'+
  '</ul>';
  h+='<p class="rb-p">대신 이렇게 바꿔보세요. “그때 나는 ○○가 서운했어. 다음엔 이렇게 해줄 수 있어?” — 사실과 감정과 부탁이 한 문장에 들어가면, 이 사주의 정확함이 장점으로 바뀝니다.</p>';
  h+='<div class="rb-key"><b>화해 한 줄</b><span>이기려는 말을 한 문장 참으면, 잃지 않을 사람을 얻습니다.</span></div>';
  return h;
}

function chLoveMistake(R,c,input,name){
  var top=c.topGodInGrp;
  var h='';
  h+='<p class="rb-p">연애에서 반복되는 실수는 성격의 문제가 아니라 <b>습관의 문제</b>예요. 이 사주에서 가장 두터운 <b>'+top+'</b>의 결이 사랑 앞에서 어떻게 어긋나는지 보면 분명해집니다.</p>';
  h+='<h4 class="rb-h">내가 반복하는 실수</h4>';
  h+='<p class="rb-p">'+LOVE_MISTAKE_GOD[top]+'</p>';
  var second=[];
  if(c.grp['인성']>=3) second.push('생각이 길어 연락이 늦고, 그 사이 상대는 마음을 접습니다.');
  if(c.grp['비겁']>=3) second.push('자존심이 올라오면 먼저 연락하기 어려워져, 둘 다 기다리는 시간이 길어집니다.');
  if(c.grp['식상']>=3) second.push('좋을 때는 표현이 넘치지만, 기분이 상하면 말이 먼저 나가 상대를 놀라게 합니다.');
  if(c.grp['관성']>=3) second.push('관계의 이름과 규칙을 먼저 정하려 해서, 상대가 부담을 느낍니다.');
  if(c.grp['재성']>=3) second.push('현실 조건을 재느라 마음이 있어도 결정을 미룹니다.');
  if(second.length){
    h+='<ul class="rb-ul">';
    for(var i=0;i<second.length;i++) h+='<li>'+second[i]+'</li>';
    h+='</ul>';
  }
  h+='<h4 class="rb-h">놓치고 있는 신호</h4>';
  h+='<p class="rb-p">이 사주는 상대의 말보다 <b>말하지 않은 것</b>을 오래 읽어요. 그래서 상대가 편하게 “괜찮아”라고 말할 때도 혼자 다른 결론을 만듭니다. 신호를 읽는 대신 <b>한 번 묻는 습관</b>이 이 사주의 연애를 가장 크게 바꿉니다.</p>';
  h+='<h4 class="rb-h">끊어내는 법 — 사흘 규칙</h4>';
  h+='<ul class="rb-ul">'+
    '<li><b>사흘</b> — 마음이 흔들린 일이 생기면 결론을 사흘 미룹니다. 이 사주는 사흘이 지나면 절반은 정리됩니다.</li>'+
    '<li><b>한 문장</b> — 그 사흘 동안 그 사람에게 하고 싶은 말을 한 문장으로만 적어둡니다. 문장이 짧아지면 감정이 정리된 것입니다.</li>'+
    '<li><b>한 번</b> — 연락은 한 번만 합니다. 두 번부터는 상대의 속도가 아니라 내 불안이 움직이는 거예요.</li>'+
  '</ul>';
  h+='<h4 class="rb-h">실수가 반복되는 구조</h4>';
  h+='<p class="rb-p">'+(c.grp['인성']>=3?'인성이 두터워 마음속에서 관계를 먼저 완성합니다. 그래서 실제 상대의 속도를 놓치고, 생각과 다른 반응에 쉽게 실망해요.':'')+(c.grp['비겁']>=3?'비겁이 두터워 자존심이 관계의 속도를 정합니다. 먼저 연락하는 것이 지는 것처럼 느껴질 때가 많아요.':'')+(c.grp['관성']>=3?'관성이 두터워 관계를 관리하려는 마음이 앞섭니다. 챙김의 강도가 세서 상대는 통제로 느낄 수 있어요.':'')+' 이 구조를 알면 실수를 의지가 아니라 <b>습관</b>으로 다룰 수 있습니다.</p>';
  h+='<h4 class="rb-h">30일 연습</h4>';
  h+='<ul class="rb-ul">'+
    '<li><b>1~10일</b> — 하루에 한 번, 상대에게 먼저 말을 겁니다. 길게 하지 않아도 됩니다.</li>'+
    '<li><b>11~20일</b> — 서운한 일이 생기면 그날 안에 “나는 ○○가 서운했어”까지만 말합니다. 결론은 다음 날로.</li>'+
    '<li><b>21~30일</b> — 한 주에 한 번, 상대가 좋아하는 것을 먼저 챙깁니다. 이 사주는 받는 것보다 주는 쪽이 편한 사람이에요.</li>'+
  '</ul>';
  h+='<h4 class="rb-h">반복되는 세 장면</h4>';
  h+='<ul class="rb-ul">'+
    '<li><b>확인하고 싶어서 시험하는 장면</b> — 답장이 늦으면 “나 없으면 어떡할 거야”를 보냅니다. 원하는 것은 확인인데 상대는 압박으로 느껴요.</li>'+
    '<li><b>좋을수록 말수가 줄어드는 장면</b> — 마음이 커질수록 조용해져서 상대는 식은 줄 압니다.</li>'+
    '<li><b>한 번에 정리하는 장면</b> — 참다가 갑자기 “그만하자”가 나옵니다. 그 말은 협박이 아니라 지친 신호예요.</li>'+
  '</ul>';
  h+='<p class="rb-p">이 세 장면이 반복된다면, 상대의 문제가 아니라 <b>내가 감정을 다루는 순서</b>의 문제예요. 느낌 → 말 → 결론 순서를 느낌 → 결론 → 말로 바꾸면 같은 실수가 줄어듭니다.</p>';
  h+='<div class="rb-key"><b>실수 한 줄</b><span>'+GOD_KEY[top]+'은 이 사람의 무기이지만, 사랑 앞에서는 결론을 서두르게 만듭니다. 결론을 사흘만 늦춰보세요.</span></div>';
  return h;
}

function chLoveCharm(R,c,input,name){
  var y=c.yongEl, d=EL_DEEP[y];
  var h='';
  h+='<p class="rb-p">연애운을 높이는 개운은 특별한 것이 아니라 <b>이 사주가 가장 편해지는 결</b>을 일상에 들이는 일이에요. 필요한 기운은 '+elB(y)+'입니다.</p>';
  h+='<h4 class="rb-h">매력이 살아나는 조건</h4>';
  h+='<p class="rb-p">'+LOVE_CHARM[y]+'</p>';
  h+='<p class="rb-p">색으로는 <b>'+d.color+'</b>, 방향은 <b>'+d.dir+'</b>이 이 사주를 편하게 해요. 데이트 장소도 '+d.dir+' 쪽, 또는 '+d.season+'의 공기가 있는 곳이 잘 맞습니다. '+d.space+'처럼 공간을 정돈해두면 만남이 자연스럽게 이어집니다.</p>';
  h+='<h4 class="rb-h">첫인상 만들기</h4>';
  h+='<ul class="rb-ul">'+
    '<li><b>말의 속도</b> — 이 사주는 빠르게 말할수록 매력이 줄어요. 한 문장을 끝까지 듣고 답하는 것만으로 인상이 달라집니다.</li>'+
    '<li><b>향</b> — '+d.taste.split('(')[0]+' 계열보다 '+EL_KO[y]+'의 결에 가까운 은은한 향이 맞아요. 강한 향은 이 사주의 차분함을 덮습니다.</li>'+
    '<li><b>사진</b> — 정면보다 옆모습, 웃는 순간의 자연스러운 표정이 이 사주의 매력을 가장 잘 담습니다.</li>'+
    '<li><b>소품</b> — '+d.item+' 하나를 늘 곁에 두세요. 대화의 실마리가 되고, 기운도 채워집니다.</li>'+
  '</ul>';
  h+='<h4 class="rb-h">이 사주가 빛나는 순간</h4>';
  h+='<p class="rb-p">'+name+' 님은 <b>누군가를 편하게 해줄 때</b> 가장 매력적이에요. 잘 보이려는 순간보다 상대의 이야기를 듣고 있는 순간에 사람이 머물게 됩니다. 그래서 소개팅보다 <b>여럿이 있는 자리</b>에서 인연이 붙는 편이에요. 나를 드러내려 애쓰지 말고, 한 사람에게 집중해보세요.</p>';
  h+='<h4 class="rb-h">데이트는 어디서</h4>';
  h+='<p class="rb-p">'+(y===0?'새로 생긴 곳, 산책로, 서점처럼 움직임이 있는 장소가 잘 맞아요. 같은 자리에 오래 앉아 있는 것보다 조금 걷는 데이트에서 대화가 풀립니다.':(y===1?'사람이 적당히 있는 밝은 곳, 공연·전시·야경처럼 분위기가 살아 있는 장소가 맞습니다. 어둡고 조용한 곳만 고르면 이 사주의 온기가 죽어요.':(y===2?'집에서 가까운 익숙한 식당, 따뜻한 조명의 공간이 맞습니다. 새로운 곳보다 “우리 단골”이 생길 때 마음이 깊어져요.':(y===3?'정돈된 공간, 취향이 분명한 작은 가게, 조용한 전시가 맞습니다. 시끄러운 곳에서는 대화가 흐려져요.':'밤의 강변, 조용한 카페, 물이 보이는 자리가 맞습니다. 늦은 시간의 긴 대화가 이 사주의 애정을 가장 크게 열어요.'))))+'</p>';
  h+='<h4 class="rb-h">3개월 매력 루틴</h4>';
  h+='<ul class="rb-ul">'+
    '<li><b>1개월</b> — '+d.color+' 계열 옷 한 벌과 '+d.item+' 하나. 눈에 닿는 것부터 바꾸세요.</li>'+
    '<li><b>2개월</b> — 말의 속도를 반 박자 늦추기. 이 사주의 매력은 속도가 아니라 여백에서 나옵니다.</li>'+
    '<li><b>3개월</b> — '+d.habit+'. 몸이 편해지면 표정이 바뀌고, 표정이 사람을 부릅니다.</li>'+
  '</ul>';
  h+='<h4 class="rb-h">말투와 사진, 향</h4>';
  h+='<p class="rb-p">이 사주는 말이 많을수록 매력이 줄고, 한 문장을 정확하게 할 때 매력이 커져요. 대화에서 <b>질문 하나와 감탄 하나</b>만 남겨보세요. 그리고 사진은 정면보다 옆모습, 웃는 순간이 좋습니다. '+d.color+' 계열의 옷을 입고 '+d.dir+' 방향의 빛을 받으면 얼굴이 가장 편해 보여요.</p>';
  h+='<p class="rb-p">향은 강한 것보다 은은한 것이 맞습니다. 처음 만나는 자리에서는 향을 하나만 쓰세요. 이 사주의 매력은 겹칠수록 흐려집니다.</p>';
  h+='<div class="rb-key"><b>매력 한 줄</b><span>'+d.color+' 계열의 옷, '+d.dir+' 쪽의 장소, 그리고 반 박자 느린 말투. 이 셋이 이 사주의 연애운을 가장 쉽게 올립니다.</span></div>';
  return h;
}

function chLoveCalendar(R,c,input,name){
  var h='';
  h+='<p class="rb-p">인연의 달력은 <b>배우자성(관성·재성)이 들어오는 달</b>과 <b>일지와 부딪히는 달</b>을 함께 봅니다. 들어오는 달에는 나가고, 부딪히는 달에는 정리에 쓰세요.</p>';
  h+=monthFlow(R,c,'love',12,'');
  var star=(input.gender==='f')?'관성':'재성';
  var ms=nextMonths(12), good=[];
  for(var i=0;i<ms.length;i++){
    var mp=monthPillarOf(ms[i].y,ms[i].m), g=tenGod(R.dStem,mp.stem);
    if(GOD_GROUP[g]===star) good.push(ms[i].y+'.'+num2(ms[i].m)+'('+g+')');
  }
  h+='<h4 class="rb-h">인연이 먼저 오는 달</h4>';
  h+='<p class="rb-p">'+(good.length?('앞으로 1년 중 배우자성인 '+star+'이 월주로 직접 들어오는 달은 <b>'+good.join(', ')+'</b>이에요. 이 달에는 새로운 자리·소개·모임이 평소보다 잘 열립니다. 거절이 두렵더라도 한 번은 나가보세요.'):('앞으로 1년에는 배우자성이 월주로 직접 들어오는 달이 뚜렷하지 않아요. 대신 사람을 소개받는 자리를 내가 만들어야 인연이 움직입니다.'))+'</p>';
  h+='<p class="rb-p">이 사주가 인연을 만나는 방식은 <b>'+ENV_BY_EL[c.yongEl]+'</b>이에요. 앱이나 소개팅보다, 누군가의 소개로 이어지는 자리가 오래 갑니다.</p>';
  h+='<h4 class="rb-h">올해 가장 중요한 석 달</h4>';
  var pick=[];
  for(var pi=0;pi<ms.length;pi++){
    var mp2=monthPillarOf(ms[pi].y,ms[pi].m), g2=tenGod(R.dStem,mp2.stem), r2=branchRel(R.dBranch,mp2.branch);
    if(GOD_GROUP[g2]===star||r2.k==='육합'||r2.k==='삼합') pick.push(ms[pi].y+'.'+num2(ms[pi].m)+'('+g2+')');
    if(pick.length>=3) break;
  }
  h+='<p class="rb-p">'+(pick.length?('이 중에서도 <b>'+pick.join(', ')+'</b>는 인연의 문이 겹치는 달이에요. 이 달에는 소개·모임·새로운 자리를 한 번씩 만들어보세요.'):'올해는 특정한 달보다 <b>매달 한 번씩 새로운 자리를 만드는 것</b>이 중요합니다. 이 사주는 스스로 문을 열 때 인연이 붙어요.')+'</p>';
  h+='<p class="rb-p">그리고 이 사주가 인연을 만나는 자리는 <b>'+ENV_BY_EL[c.yongEl]+'</b>예요. 화려한 자리보다 조용히 오래 이야기할 수 있는 자리에서 마음이 열립니다.</p>';
  h+='<div class="rb-key"><b>1년 사용법</b><span>배우자성이 오는 달에는 밖으로, 충이 오는 달에는 안으로. 그 리듬만 지켜도 같은 1년이 다르게 지나갑니다.</span></div>';
  return h;
}

