function coupleScore(R,pR){
  var me=R.dayEl, pa=pR.dayEl, s=50, notes=[];
  if(me===pa){ s+=8; notes.push('일간이 같은 오행이라 통하는 부분이 많아요'); }
  else if(generates(pa,me)){ s+=14; notes.push('상대의 기운이 나를 살려요'); }
  else if(generates(me,pa)){ s+=11; notes.push('내 기운이 상대를 살려요'); }
  else if(controls(me,pa)){ s+=2; notes.push('내가 상대를 누르는 구조예요'); }
  else if(controls(pa,me)){ s+=3; notes.push('상대가 나를 누르는 구조예요'); }
  var br=branchRel(R.dBranch,pR.dBranch); s+=br.s; notes.push('일지가 '+br.k+'의 관계예요');
  var fill=0;
  for(var i=0;i<5;i++){
    if(pR.count[i]===0&&R.count[i]>=2){ s+=4; fill++; }
    if(R.count[i]===0&&pR.count[i]>=2){ s+=4; fill++; }
  }
  if(fill) notes.push('서로 비어 있는 기운을 '+fill+'가지 채워줘요');
  s=Math.max(40,Math.min(96,Math.round(s)));
  return {s:s,notes:notes,br:br};
}
function chMarriageBase(R,c,input,name){
  var pc=partnerChart(input), h='';
  h+='<p class="rb-p">궁합은 “잘 맞는다/안 맞는다”를 정하는 표가 아니에요. 두 사람의 여덟 글자가 <b>어디에서 붙고 어디에서 부딪히는지</b>를 미리 알아두면, 같은 싸움을 덜 하게 됩니다.</p>';
  if(!pc){
    h+='<h4 class="rb-h">내 배우자궁의 결</h4>';
    h+='<p class="rb-p">이 사주의 배우자궁은 일지 '+brB(R.dBranch)+'예요. 인연의 결은 <b>'+SPOUSE[R.dBranch]+'</b> 쪽이고, '+BR_INNER[R.dBranch]+' 그래서 이 사주는 화려한 사람보다 <b>생활의 결이 맞는 사람</b>에게 마음을 둡니다.</p>';
    h+='<p class="rb-p">함께 볼 사람의 생년월일을 넣으면 두 사람의 일간·일지가 만나는 자리, 오행이 서로를 채우는지, 올해 두 사람 사이에 어떤 기운이 흐르는지까지 짚어드릴 수 있어요. 위의 「함께 볼 사람」에 상대의 생년월일을 적고 다시 열어보세요.</p>';
    h+='<h4 class="rb-h">어떤 사람과 오래 가는가</h4>';
  h+='<p class="rb-p">일지 '+brB(R.dBranch)+'는 배우자가 놓이는 자리예요. 이 사주는 <b>'+SPOUSE[R.dBranch]+'</b> 쪽의 사람과 오래 갑니다. '+BR_INNER[R.dBranch]+' 그래서 첫눈에 끌리는 사람보다, 몇 번 만나야 편해지는 사람이 결국 남습니다.</p>';
  h+='<p class="rb-p">'+(input.gender==='f'?'여성 사주에서 배우자를 보는 창은 관성(官星)이에요. 이 사주는 관성이 '+c.grp['관성']+'개로, '+(c.grp['관성']>=3?'배우자와의 관계가 삶의 중심이 됩니다. 안정된 관계에서 힘이 나고, 관계가 흔들리면 일도 흔들려요.':(c.grp['관성']>=1?'한 번 정하면 오래 가는 편입니다. 다만 자신의 기준을 먼저 세우고 만나야 흔들리지 않아요.':'관계가 삶의 우선순위에 잘 오르지 않습니다. 마음이 생긴 달에는 한 번 더 연락해보세요.')):'남성 사주에서 배우자를 보는 창은 재성(財星)이에요. 이 사주는 재성이 '+c.grp['재성']+'개로, '+(c.grp['재성']>=3?'현실적인 조건과 마음이 함께 가는 관계를 원합니다. 생활이 맞는 사람에게 마음이 오래 머물러요.':(c.grp['재성']>=1?'마음이 있어도 조건을 함께 보는 편입니다. 그 균형이 오래 가는 힘이 돼요.':'조건보다 마음이 앞서는 편입니다. 생활의 리듬을 함께 확인하는 대화가 필요해요.')))+'</p>';
  h+='<h4 class="rb-h">결혼 전에 확인할 세 가지</h4>';
  h+='<ul class="rb-ul">'+
    '<li><b>생활비</b> — 각자 얼마를 내고 무엇을 공동으로 할지. 이 사주는 이 대화를 미루면 감정으로 되돌아옵니다.</li>'+
    '<li><b>거주지</b> — 양가와의 거리. 이 사주는 가까울수록 책임이 몰리는 편이에요.</li>'+
    '<li><b>역할</b> — 집안일과 양가 일정. “알아서 하겠지”가 가장 위험합니다.</li>'+
  '</ul>';
  h+='<p class="rb-p">이 세 가지를 정하지 않고 마음만 확인하면, 결혼 후 첫 1년에 그 대화가 갈등의 형태로 다시 옵니다. 미리 정해두는 것이 관계를 식히는 일이 아니라 <b>오래 가게 하는 일</b>이에요.</p>';
  h+='<p class="rb-p">그리고 이 사주는 결혼을 <b>감정의 완성</b>으로 생각하는 편이에요. 하지만 결혼은 감정이 아니라 <b>생활의 계약</b>에 가깝습니다. 그 사실을 미리 받아들이면, 결혼 후의 서운함이 훨씬 줄어듭니다.</p>';
  h+='<div class="rb-key"><b>지금 해볼 것</b><span>상대의 생년월일만 있으면 궁합의 뼈대가 보입니다. 시간(시주)은 없어도 괜찮아요.</span></div>';
    return h;
  }
  var pR=pc.R, sc=coupleScore(R,pR);
  var band=sc.s>=85?'손이 잘 맞는 인연':(sc.s>=70?'편안히 오래 가는 인연':(sc.s>=55?'노력이 필요한 인연':'서로 다른 결을 배우는 인연'));
  h+='<div class="rb-special"><div class="sh"><i>合</i>두 사람의 기본 궁합</div>';
  h+='<div class="score"><div class="num">'+sc.s+'<small>점</small></div><div class="mt"><div class="bar"><i style="width:'+sc.s+'%"></i></div><span>명리 참고 지수 · '+band+'</span></div></div>';
  h+='<p>'+sc.notes.join(', ')+'는 점을 반영했어요. 이 숫자는 두 사람의 글자만으로 계산한 참고값입니다.</p>';
  h+='<p class="disc-sm">상대의 시간(시주)과 실제 관계의 맥락은 반영되지 않았습니다. 결과를 정하는 표가 아닙니다.</p></div>';
  h+='<h4 class="rb-h">두 사람의 일간이 만나는 자리</h4>';
  h+='<p class="rb-p">'+name+' 님은 '+stemB(R.dStem)+', 상대는 '+stemB(pR.dStem)+'이에요. '+sc.br.t+'</p>';
  h+='<p class="rb-p">일간의 관계는 관계의 <b>기본 온도</b>를 정합니다. 같은 오행이면 편하지만 자극이 적고, 상생이면 한쪽이 다른 쪽을 살립니다. 상극이면 끌림이 강한 대신 생활에서 부딪힙니다. 어느 쪽이든 <b>오래 가는지는 두 사람이 시간을 어떻게 쓰느냐</b>가 정합니다.</p>';
  h+='<h4 class="rb-h">인연의 무게</h4>';
  var fill=[];
  for(var i=0;i<5;i++){
    if(pR.count[i]===0&&R.count[i]>=2) fill.push('상대에게 없는 '+EL_KO[i]+' 기운을 내가 넉넉히 가지고 있어요');
    if(R.count[i]===0&&pR.count[i]>=2) fill.push('내게 없는 '+EL_KO[i]+' 기운을 상대가 채워줄 수 있어요');
  }
  h+='<p class="rb-p">'+(fill.length?fill.join('. ')+'. 이 보완이 두 사람이 오래 가는 이유예요. 다만 채워주는 쪽이 늘 같은 사람이면 그 사람이 지칩니다. 돌아가며 채워주는 규칙을 만드세요.':'두 사람의 오행이 서로를 크게 보완하지도 비우지도 않아요. 대신 생활의 규칙을 함께 정할수록 관계가 안정됩니다. 비슷한 사람끼리는 규칙이 없으면 같은 자리에서 계속 부딪힙니다.')+'</p>';
  h+='<p class="rb-p">이 사주에서 인연의 무게는 <b>'+GOD_KEY[c.topGodInGrp]+'</b>으로 나타나고, 상대는 <b>'+GOD_KEY[pc.c.topGodInGrp]+'</b>으로 받습니다. 같은 사랑도 이 두 방식이 다르기 때문에, 표현이 어긋나면 마음이 없는 것처럼 보입니다.</p>';
  h+='<h4 class="rb-h">궁합을 보는 순서</h4>';
  h+='<p class="rb-p">첫째, <b>일간</b>을 봅니다. 두 사람이 서로를 살리는지, 누르는지가 관계의 기본 온도를 정해요. 둘째, <b>일지</b>를 봅니다. 생활의 리듬이 붙는지, 부딪히는지가 결혼생활의 피로도를 정합니다. 셋째, <b>비어 있는 기운</b>을 봅니다. 상대가 내게 없는 것을 채워주는지가 오래 가는 힘이 됩니다.</p>';
  h+='<p class="rb-p">이 순서를 지키면 “좋다/나쁘다”가 아니라 <b>어디를 조율해야 하는지</b>가 보입니다. 궁합이 좋은 두 사람도 생활의 규칙이 없으면 다투고, 궁합이 무난한 두 사람도 규칙이 있으면 오래 갑니다.</p>';
  h+='<h4 class="rb-h">결혼 전에 확인할 세 가지</h4>';
  h+='<ul class="rb-ul">'+
    '<li><b>생활비</b> — 각자 얼마를 내고, 무엇을 공동으로 할지. 이 사주는 이 대화를 미루면 나중에 감정으로 되돌아옵니다.</li>'+
    '<li><b>거주지</b> — 양가와의 거리. 이 사주는 가까울수록 책임이 몰리는 편이에요.</li>'+
    '<li><b>역할</b> — 집안일과 양가 일정. “알아서 하겠지”가 가장 위험합니다.</li>'+
  '</ul>';
  h+='<p class="rb-p">이 세 가지를 정하지 않고 마음만 확인하면, 결혼 후 첫 1년에 그 대화가 갈등의 형태로 다시 옵니다. 미리 정해두는 것이 관계를 식히는 일이 아니라 <b>오래 가게 하는 일</b>이에요.</p>';
  h+='<h4 class="rb-h">궁합이 나빠도 오래 가는 이유</h4>';
  h+='<p class="rb-p">궁합은 관계의 성패를 정하지 않아요. 점수가 낮은 두 사람도 생활의 규칙이 있으면 오래 가고, 높은 두 사람도 규칙이 없으면 같은 자리에서 반복해서 부딪힙니다. 이 사주는 특히 <b>말의 순서</b>가 중요해요. 결론을 먼저 말하면 상대는 과정을 묻고, 과정을 먼저 말하면 상대는 결론을 기다립니다.</p>';
  h+='<p class="rb-p">그래서 궁합을 볼 때는 점수보다 <b>“싸운 뒤에 어떻게 화해하는가”</b>를 보세요. 그 방식이 두 사람에게 이미 있다면, 어떤 조합도 버틸 수 있습니다.</p>';
  h+='<h4 class="rb-h">인연의 무게를 재는 법</h4>';
  h+='<p class="rb-p">인연의 무게는 설렘의 크기가 아니라 <b>서로의 빈 곳을 채워주는 정도</b>로 잽니다. 이 사주는 '+elB(c.yongEl)+'이 필요하고, 상대는 '+elB(pc.c.yongEl)+'이 필요해요. 두 사람이 서로의 필요한 결을 조금씩 가지고 있다면, 오래 함께할수록 편해집니다.</p>';
  h+='<div class="rb-key"><b>기본 궁합 한 줄</b><span>'+band+' · '+sc.s+'점. 점수보다 중요한 것은 두 사람이 싸운 뒤 다시 말을 거는 방식입니다.</span></div>';
  return h;
}

function chMarriageHabit(R,c,input,name){
  var pc=partnerChart(input), h='';
  h+='<p class="rb-p">결혼생활을 오래 힘들게 하는 것은 큰 사건이 아니라 <b>생활의 리듬</b>이에요. 잠드는 시간, 집안일을 처리하는 방식, 대화가 시작되는 시간 — 이 세 가지가 어긋나면 애정이 있어도 피곤해집니다.</p>';
  h+='<h4 class="rb-h">내 생활 습관의 결</h4>';
  h+='<p class="rb-p">일지 '+brB(R.dBranch)+'의 결은 이렇습니다. '+MARR_HABIT_BR[R.dBranch]+'</p>';
  h+='<p class="rb-p">여기에 <b>'+c.topGrp+'</b>이 두터워 '+GROUP_MEAN[c.topGrp]+' 그래서 이 사주는 생활에서 '+GOD_KEY[c.topGodInGrp]+'을 기준으로 판단합니다. 상대가 이 기준을 모르면 “왜 저렇게까지” 싶은 장면이 반복돼요.</p>';
  if(pc){
    var pR=pc.R;
    h+='<h4 class="rb-h">상대의 생활 습관</h4>';
    h+='<p class="rb-p">상대의 일지 '+brB(pR.dBranch)+'는 이렇습니다. '+MARR_HABIT_BR[pR.dBranch]+'</p>';
    var same=(R.dBranch===pR.dBranch);
    h+='<p class="rb-p">'+(same?'두 사람의 일지가 같아요. 생활의 리듬이 비슷해서 같이 있으면 편하지만, 같은 약점도 함께 커집니다. 둘 다 미루는 날에는 집이 그대로 남아 있어요.':'두 사람의 일지가 달라서 생활의 리듬이 어긋나기 쉬워요. 어느 쪽이 옳다가 아니라 <b>시간을 나누는 규칙</b>이 필요합니다. 예를 들어 평일 저녁은 각자, 주말 오전은 함께처럼 경계를 정해두세요.')+'</p>';
    h+='<h4 class="rb-h">대화 코드의 차이</h4>';
    h+='<p class="rb-p">'+name+' 님은 <b>'+c.topGrp+'</b>의 방식으로 말하고, 상대는 <b>'+pc.c.topGrp+'</b>의 방식으로 듣습니다. '+GROUP_MEAN[pc.c.topGrp]+' 그래서 이 사주가 결론부터 말하면 상대는 과정을 묻고, 이 사주가 과정을 설명하면 상대는 결론을 기다립니다. 대화가 길어지는 이유가 여기 있어요.</p>';
    h+='<p class="rb-p">해법은 간단합니다. 이 사주가 <b>결론을 먼저</b>, 상대가 <b>과정을 먼저</b> 꺼내는 순서를 정하세요. “나 오늘 이런 일이 있었어” 다음에 “그래서 이렇게 하고 싶어”를 붙이는 식입니다.</p>';
  } else {
    h+='<h4 class="rb-h">상대와 맞출 지점</h4>';
    h+='<p class="rb-p">상대의 생년월일을 넣으면 상대의 생활 리듬까지 겹쳐볼 수 있어요. 지금은 이 사주가 결혼생활에서 반복해서 요구하게 될 것부터 정리합니다.</p>';
    h+='<p class="rb-p">이 사주는 <b>'+GOD_KEY[c.topGodInGrp]+'</b>을 중요하게 여겨서, 상대가 그 부분을 가볍게 넘기면 마음이 닫힙니다. 결혼 전에 “우리 집에서 이건 꼭 지키자”를 세 가지로 정해두면, 이후의 갈등이 훨씬 줄어듭니다.</p>';
  }
  h+='<h4 class="rb-h">생활 습관 체크리스트</h4>';
  h+='<ul class="rb-ul">'+
    '<li><b>아침</b> — 이 사주는 '+(R.dayEl===4||R.dayEl===0?'아침에 말수가 적습니다. 상대가 아침 인사를 중요하게 여기면 “무관심”으로 오해될 수 있어요. 짧게라도 눈을 맞추세요.':'아침에 기운이 올라갑니다. 아침에 중요한 대화를 꺼내면 잘 통합니다.')+'</li>'+
    '<li><b>저녁</b> — '+(R.dayEl===1||R.dayEl===3?'저녁에 감정이 깊어집니다. 늦은 시간의 대화는 좋지만, 결론은 다음 날로 미루세요.':'저녁에는 에너지가 떨어집니다. 무거운 이야기는 피하고, 함께 먹는 시간으로 쓰세요.')+'</li>'+
    '<li><b>집안일</b> — 이 사주는 '+ (c.topGrp==='관성'?'정해진 역할이 있을 때 편합니다. 표를 만들어 눈에 보이게 두세요.':(c.topGrp==='식상'?'즉흥적으로 하기보다 같이 할 때 재미가 붙습니다. 함께 하는 요리·정리가 잘 맞아요.':(c.topGrp==='인성'?'혼자 정리하는 시간이 필요합니다. “같이 하자”보다 “네가 할 것만 정해줘”가 편해요.':'주도권을 나눌 때 편합니다. 역할은 정하되 서로의 방식은 인정해주세요.'))) +'</li>'+
    '<li><b>주말</b> — 하나는 함께, 하나는 각자. 이 사주는 둘 다 함께 하면 지치고, 둘 다 따로 하면 멀어집니다.</li>'+
  '</ul>';
  h+='<h4 class="rb-h">결혼 첫 1년의 규칙</h4>';
  h+='<p class="rb-p">첫 1년은 서로의 습관을 배우는 기간이에요. 이 사주는 이 시기에 <b>상대를 고치려는 마음</b>이 가장 강해집니다. 고치려는 말 대신 “나는 이렇게 하는 게 편해”로 바꾸세요. 같은 내용도 훨씬 덜 부딪힙니다.</p>';
  h+='<p class="rb-p">그리고 하루 15분, 화면 없이 이야기하는 시간을 첫 1년에 정해두세요. 이 습관이 자리 잡으면 이후의 갈등이 훨씬 빨리 풀립니다.</p>';
  h+='<h4 class="rb-h">잠과 돈, 두 가지 생활 코드</h4>';
  h+='<p class="rb-p">이 사주는 '+(R.dayEl===4||R.dayEl===0?'밤에 생각이 깊어지는 편이라, 잠드는 시간이 늦어지면 아침의 관계가 서먹해집니다. 상대와 잠드는 시간을 크게 다르게 두지 않는 편이 좋아요.':'아침에 기운이 올라가는 편이라, 아침의 짧은 대화가 하루의 관계를 정합니다.')+' 그리고 돈은 '+(c.topGrp==='재성'?'계획적으로 쓰는 편이라 상대의 즉흥 지출이 불안하게 느껴집니다. 예산의 큰 틀만 함께 정하세요.':(c.topGrp==='인성'?'안전을 위해 모으는 편이라 함께 쓰는 즐거움이 부족할 수 있어요. 한 달에 한 번은 같이 쓰는 날을 만드세요.':'쓰는 흐름이 유연한 편이라 상대가 계획형이면 답답해합니다. 고정비만 맞추고 나머지는 자유롭게 두세요.'))+'</p>';
  h+='<div class="rb-key"><b>생활 궁합 한 줄</b><span>잠드는 시간과 집안일의 기준, 이 두 가지만 합의해도 결혼생활의 절반이 정리됩니다.</span></div>';
  return h;
}

function chMarriageIntimacy(R,c,input,name){
  var pc=partnerChart(input), h='';
  h+='<p class="rb-p">부부의 친밀감은 애정의 크기보다 <b>온도의 차이</b>에서 어긋납니다. 한 사람은 표현으로 확인하고, 다른 사람은 함께 있는 시간으로 확인하기 때문이에요.</p>';
  h+='<h4 class="rb-h">내 애정 표현의 온도</h4>';
  h+='<p class="rb-p">'+MARR_TEMP[R.dayEl]+'</p>';
  h+='<p class="rb-p">명리에서 부부의 자리는 일지이고, 애정의 세기는 <b>'+(input.gender==='f'?'관성':'재성')+'</b>이 보여줍니다. 이 사주는 '+(input.gender==='f'?'관성':'재성')+'이 <b>'+c.grp[(input.gender==='f'?'관성':'재성')]+'개</b>로 '+(c.grp[(input.gender==='f'?'관성':'재성')]>=3?'넉넉한 편이에요. 애정을 확인하고 싶은 마음이 크고, 상대의 반응에 예민해집니다.':(c.grp[(input.gender==='f'?'관성':'재성')]>=1?'고르게 놓여 있어, 표현은 많지 않아도 필요할 때 분명하게 합니다.':'얇은 편이라 먼저 표현하는 일이 어색합니다. 상대가 다가와야 마음이 열리는 쪽이에요.'))+'</p>';
  if(pc){
    h+='<h4 class="rb-h">두 사람의 온도차</h4>';
    h+='<p class="rb-p">상대의 일간은 '+eko(pc.R.dayEl)+'이라 '+MARR_TEMP[pc.R.dayEl]+'</p>';
    var gap=Math.abs(R.dayEl-pc.R.dayEl);
    h+='<p class="rb-p">'+(gap===0?'두 사람의 온도가 비슷해요. 그래서 서로의 필요를 잘 알지만, 둘 다 표현을 미루면 관계가 조용히 식습니다. 한 달에 한 번은 먼저 손을 내미는 쪽이 되어보세요.':(gap===2||gap===3?'온도의 방향이 달라요. 한 사람은 말로, 다른 사람은 행동으로 애정을 확인합니다. 상대의 언어를 배우지 않으면 애정이 있어도 전달되지 않아요.':'온도의 높낮이가 달라요. 한 사람이 더 자주 확인을 원하고, 다른 사람은 혼자만의 여백이 필요합니다. 이 차이를 “사랑이 부족하다”로 읽지 말고 “충전 방식이 다르다”로 읽어야 오래 갑니다.'))+'</p>';
    h+='<p class="rb-p">부부 사이의 친밀감은 <b>하루 15분의 대화</b>에서 가장 크게 회복됩니다. 잠자리보다 먼저, 화면을 내려놓고 서로의 하루를 말하는 시간을 정해보세요. 정서적 온도가 맞으면 나머지는 따라옵니다.</p>';
  } else {
    h+='<p class="rb-p">이 사주는 친밀감을 <b>말보다 함께 있는 시간</b>으로 확인하는 편이에요. 상대가 말로 표현하지 않는다고 애정이 없는 게 아니라는 걸, 이 사주도 반대로 기억해야 합니다. 두 사람의 온도차를 알려면 상대의 생년월일을 함께 넣어보세요.</p>';
  }
  h+='<h4 class="rb-h">정서 온도를 맞추는 법</h4>';
  h+='<p class="rb-p">온도차는 사랑의 크기 차이가 아니에요. 한 사람은 <b>말로</b> 확인하고, 다른 사람은 <b>함께 있는 시간</b>으로 확인합니다. 이 사주는 '+(R.dayEl===1||R.dayEl===3?'표현이 분명한 쪽이라 상대가 반응하지 않으면 서운함이 빨리 커집니다.':'표현이 적은 쪽이라 상대가 확인을 요구하면 부담을 느낍니다.')+' 그래서 상대의 언어를 한 번 배워두면 관계가 훨씬 편해져요.</p>';
  h+='<ul class="rb-ul">'+
    '<li><b>하루 15분</b> — 잠들기 전, 화면 없이 서로의 하루를 말합니다. 이 사주는 짧고 자주가 효과적이에요.</li>'+
    '<li><b>주 1회 손길</b> — 말로 표현하기 어려우면 손을 잡거나 어깨를 만지는 것으로 충분합니다. 이 사주는 몸의 온도에 민감합니다.</li>'+
    '<li><b>월 1회 확인</b> — “요즘 내가 부족한 게 있어?”를 묻는 날을 정하세요. 이 사주는 서운함을 쌓아두는 편이라 정기적인 확인이 약이 됩니다.</li>'+
  '</ul>';
  h+='<h4 class="rb-h">조심할 말</h4>';
  h+='<p class="rb-p">이 사주에게 가장 아픈 말은 <b>“당신은 나를 사랑하지 않아”</b>예요. 실제로는 반대인데도 그 말을 들으면 마음이 먼저 닫힙니다. 상대도 이 사주에게 “당신은 이해를 못 해”라고 말하면 같은 일이 반복돼요. 싸울 때 이 두 문장만 피해도 관계가 훨씬 오래 갑니다.</p>';
  h+='<h4 class="rb-h">스킨십의 온도</h4>';
  h+='<p class="rb-p">이 사주는 '+ (R.dayEl===1||R.dayEl===3?'스킨십으로 애정을 확인하는 편이에요. 말보다 손길이 먼저일 때 마음이 풀립니다. 상대가 표현을 아끼면 서운함이 빨리 커져요.':(R.dayEl===0||R.dayEl===4?'스킨십은 적어도 괜찮지만, 대신 깊은 대화가 필요합니다. 말없이 오래 곁에 있는 것만으로도 애정이 전달돼요.':'스킨십보다 함께하는 활동에서 친밀감을 느낍니다. 같이 걷고, 같이 먹고, 같이 무언가를 만들 때 가까워져요.'))+'</p>';
  h+='<p class="rb-p">부부 사이에서 가장 중요한 것은 <b>거절을 관계의 거절로 받아들이지 않는 것</b>이에요. 오늘은 피곤해서가 아니라, 그 순간의 컨디션일 뿐이라고 말해주세요. 이 사주는 그 한마디를 오래 기억합니다.</p>';
  h+='<div class="rb-key"><b>친밀감 한 줄</b><span>온도가 다르면 사랑이 없는 게 아니라 전달 방식이 다른 것입니다. 상대의 언어로 한 번 표현해보세요.</span></div>';
  return h;
}

function chMarriageMoney(R,c,input,name){
  var pc=partnerChart(input), h='';
  h+='<p class="rb-p">결혼생활에서 가장 자주 다투는 것은 애정이 아니라 <b>돈과 가사, 그리고 양가</b>예요. 이 세 가지는 사랑으로 해결되지 않아서 미리 구조를 정해두는 편이 좋습니다.</p>';
  h+='<h4 class="rb-h">내가 돈을 쓰는 방식</h4>';
  h+='<p class="rb-p">'+MARR_MONEY_GRP[c.topGrp]+'</p>';
  var jeong=c.gc['정재'], pyeon=c.gc['편재'];
  h+='<p class="rb-p">재성은 정재 <b>'+jeong+'개</b>, 편재 <b>'+pyeon+'개</b>예요. '+(pyeon>jeong?'변동이 있는 수입에 익숙한 사주라, 살림도 유동적입니다. 고정비를 먼저 정하고 나머지를 쓰는 구조가 맞아요.':(jeong>pyeon?'고정된 구조를 좋아하는 사주라, 예산을 정해두면 안정됩니다. 다만 상대가 즉흥적으로 쓰면 불안해져요.':'고정과 변동이 반반이라, 큰 틀만 정하고 세부는 자유롭게 두는 방식이 잘 맞습니다.'))+'</p>';
  h+='<h4 class="rb-h">가사와 역할</h4>';
  var gw=c.grp['관성'];
  h+='<p class="rb-p">'+(gw>=3?'관성이 두터워 역할과 규칙이 분명할 때 편해요. 가사를 “누가 무엇을” 정해두면 강하지만, 상대가 다르게 생각하면 서운함이 오래갑니다.':(gw>=2?'역할을 나누는 것에 거부감이 없어요. 다만 “알아서 하겠지”에 기대면 한쪽으로 쏠립니다.':'관성이 얇아 정해진 역할보다 그때그때 하는 쪽이 편해요. 대신 기준이 없으면 늘 같은 사람이 치웁니다.'))+'</p>';
  h+='<h4 class="rb-h">양가 관계</h4>';
  h+='<p class="rb-p">년주는 조상과 초년, 월주는 부모와 청년을 봅니다. 이 사주는 년주 '+brB(R.yIdx%12)+', 월주 '+brB(R.mIdx%12)+'로, '+(c.grp['인성']>=3?'부모·가족의 영향이 두터운 편이에요. 결혼 후에도 양가의 기대가 관계에 들어오기 쉬우니, 부부가 먼저 결론을 정하고 각자 부모에게 말하는 방식을 지키세요.':'양가와의 거리를 스스로 조절하는 편이에요. 다만 명절·경조사처럼 정해진 일은 미리 역할을 나눠두면 마찰이 줄어듭니다.')+'</p>';
  if(pc){
    h+='<p class="rb-p">상대는 <b>'+pc.c.topGrp+'</b>의 방식으로 살림을 봐요. '+MARR_MONEY_GRP[pc.c.topGrp]+' 두 사람의 돈 기준이 다르면, “아껴야 한다”와 “써야 한다”가 아니라 <b>무엇에 쓰는 돈인지</b>를 먼저 합의하세요.</p>';
  }
  h+='<ul class="rb-ul">'+
    '<li><b>공동 계좌</b> — 생활비만 넣고, 각자 용돈은 따로 두세요. 전부를 합치면 이 사주는 통제받는다고 느낍니다.</li>'+
    '<li><b>큰 지출 기준</b> — 금액을 정해두고, 그 이상은 하루 자고 함께 결정하세요.</li>'+
    '<li><b>양가 지원</b> — 금액과 횟수를 부부가 먼저 정하고, 각자 부모에게 전달하세요.</li>'+
  '</ul>';
  h+='<h4 class="rb-h">돈 대화 스크립트</h4>';
  h+='<p class="rb-p">이 사주는 돈 이야기를 감정으로 꺼내기 쉬워요. “당신은 왜 맨날 쓰기만 해” 대신 <b>“이번 달 고정비가 이만큼인데, 다음 달엔 이걸 줄여보면 어때”</b>처럼 숫자와 제안으로 말하세요. 숫자는 감정을 낮춥니다.</p>';
  h+='<p class="rb-p">그리고 한 달에 한 번, <b>30분 예산 회의</b>를 정해두세요. 이 사주는 구조가 있으면 안정되고, 없으면 불안해집니다. 회의는 길게 하지 말고 세 가지만 확인해요 — 들어온 돈, 나간 돈, 다음 달 큰 지출.</p>';
  h+='<h4 class="rb-h">양가와의 거리 규칙</h4>';
  h+='<ul class="rb-ul">'+
    '<li><b>결론은 부부가 먼저</b> — 부모에게 말하기 전에 두 사람이 정합니다. 이 사주는 이 순서가 뒤집히면 배신감을 느껴요.</li>'+
    '<li><b>각자 부모에게</b> — 내 부모에게는 내가 말합니다. 상대가 대신 말하면 오해가 커져요.</li>'+
    '<li><b>금액과 횟수</b> — 지원은 금액과 횟수를 먼저 정합니다. 정해두지 않으면 매번 감정이 붙습니다.</li>'+
  '</ul>';
  h+='<p class="rb-p">이 세 규칙을 결혼 전에 말로 합의해두면, 명절·경조사 때 생기는 갈등의 절반이 사라집니다.</p>';
  h+='<div class="rb-key"><b>현실 궁합 한 줄</b><span>돈은 합치지 말고 구조를 합치세요. 통장은 나누되 기준은 하나로.</span></div>';
  return h;
}

function dangerYears(R){
  var out=[];
  for(var i=0;i<R.seun.length;i++){ if(mod(R.seun[i].idx%12-R.dBranch,12)===6) out.push(R.seun[i].year+'년'); }
  return out.length?out.join(', '):R.seun[0].year+'~'+R.seun[4].year+'년 중 충하는 해는 없고';
}
function chWeddingTiming(R,c,input,name){
  var h='', star=(input.gender==='f')?'관성':'재성';
  var ms=nextMonths(12), good=[];
  for(var i=0;i<ms.length;i++){
    var mp=monthPillarOf(ms[i].y,ms[i].m), g=tenGod(R.dStem,mp.stem);
    if(GOD_GROUP[g]===star) good.push(ms[i].y+'.'+num2(ms[i].m));
  }
  var yrs=seunYearsByGroup(R,star);
  h+='<p class="rb-p">결혼의 적기는 <b>배우자성('+star+')이 들어오는 해</b>와 <b>일지에 합이 오는 해</b>를 겹쳐 봅니다. 여기에 지금 대운이 그 자리를 밀어주는지까지 확인하면 시기가 분명해져요.</p>';
  h+='<h4 class="rb-h">해 단위로 보는 적기</h4>';
  if(yrs.length){
    h+='<p class="rb-p">앞으로 5년 중 '+star+'이 세운으로 들어오는 해는 <b>'+yrs.map(function(o){return o.y+'년('+o.g+')';}).join(', ')+'</b>이에요. 이 해에는 만남이 다음 단계로 넘어가거나, 결혼을 결정하는 이야기가 나오기 쉽습니다. 다만 세운은 <b>문이 열리는 시기</b>를 알려줄 뿐이에요. 그 문을 지나가는 것은 두 사람의 결정입니다.</p>';
  } else {
    h+='<p class="rb-p">앞으로 5년에는 '+star+'이 세운으로 직접 들어오지 않아요. 그래서 해보다 <b>지금 대운과 사람을 만나는 자리의 밀도</b>가 중요합니다. 이 시기는 결혼을 서두르기보다 상대를 정확히 알아가는 데 쓰는 편이 낫습니다.</p>';
  }
  var sy=null;
  for(var k=0;k<R.seun.length;k++){
    var diff=mod(R.seun[k].idx%12-R.dBranch,12);
    if(diff===4||diff===8) sy=R.seun[k].year;
  }
  if(sy) h+='<p class="rb-p">특히 <b>'+sy+'년</b>은 일지와 합이 들어오는 해라, 사람을 통해 관계가 정리되는 힘이 있어요. 소개·상견례·양가 인사처럼 <b>사람이 개입하는 일</b>이 이 해에 잘 풀립니다.</p>';
  h+='<h4 class="rb-h">달 단위로 보는 적기</h4>';
  h+='<p class="rb-p">'+(good.length?'올해와 내년 중 '+star+'이 월주로 들어오는 달은 <b>'+good.join(', ')+'</b>이에요. 상견례·예식장·집을 보는 일처럼 구체적인 약속은 이 달에 잡으면 잘 진행됩니다.':(R.seun[0].year+'~'+R.seun[4].year+'년에는 '+star+'이 월주로 뚜렷하게 들어오는 달이 적어요. 날짜를 고르기보다 두 사람의 생활 기반이 준비되는 시기를 먼저 보세요.'))+'</p>';
  h+='<h4 class="rb-h">지금 결혼을 서두르면 안 되는 이유</h4>';
  h+='<p class="rb-p">이 사주는 '+(R.strength==='강'?'마음을 정하면 빠르게 밀어붙이는 편이라, 준비가 덜 된 상태에서 결정하면 나중에 혼자 감당하는 일이 많아집니다.':(R.strength==='약'?'상대와 주변의 확신을 확인해야 움직이는 편이라, 재촉받으면 마음과 다른 결정을 합니다.':'상황을 보며 결정하는 편이라, 주변의 압박이 커지면 판단이 흐려집니다.'))+' 결혼은 <b>날짜보다 조건</b>이 먼저예요. 두 사람의 생활비, 거주지, 양가와의 거리 이 세 가지가 정리된 뒤에 날짜를 잡으세요.</p>';
  if(input.ctx&&input.ctx.stage) h+='<p class="rb-p">'+STAGE_LINE[input.ctx.stage]+'</p>';
  h+='<h4 class="rb-h">결혼 준비의 순서</h4>';
  h+='<p class="rb-p">이 사주는 준비를 한꺼번에 몰아넣으면 결정의 질이 떨어집니다. 순서를 나눠서 하세요. ① 두 사람의 생활 조건 정리(돈·거주지·역할) → ② 양가 인사와 예산 합의 → ③ 날짜와 장소 → ④ 세부 준비. ①과 ②가 끝나기 전에 ③을 정하면, 나중에 조건이 바뀌며 감정이 상합니다.</p>';
  h+='<h4 class="rb-h">피해야 할 해와 달</h4>';
  h+='<p class="rb-p">'+(dangerYears(R))+' 같은 해는 일지와 부딪혀 생활의 판이 바뀌기 쉬워요. 이 해에 결혼을 서두르면 준비보다 감정 소모가 커집니다. 결혼식 날짜만 고를 때도 <b>일지와 충하는 날</b>은 피하고, 합이 되는 날을 고르세요.</p>';
  h+='<p class="rb-p">다만 날짜는 참고일 뿐이에요. 이 사주에게 결혼의 성패를 가르는 것은 날짜가 아니라 <b>생활 조건과 역할 합의</b>입니다. 그 두 가지가 정리되었으면, 날짜는 생각보다 유연하게 정해도 됩니다.</p>';
  var firstLine=(yrs.length)?(yrs[0].y+'년이 첫 문'+(yrs[1]?(' · '+yrs[1].y+'년이 두 번째 문'):'')+'입니다. 문이 열린 해에 조건을 정리해두면 다음 해에 자연스럽게 진행됩니다.'):'이 시기는 해보다 조건을 정리하는 데 쓰세요. 생활비·거주지·양가와의 거리가 정리되면 날짜는 따라옵니다.';
  h+='<div class="rb-key"><b>적기 한 줄</b><span>'+firstLine+'</span></div>';
  return h;
}

function chCrisis(R,c,input,name){
  var pc=partnerChart(input), h='';
  h+='<p class="rb-p">부부의 위기는 갑자기 오지 않아요. 대개 <b>작은 신호 → 반복 → 침묵</b>의 순서로 옵니다. 이 사주에서 그 신호가 어떤 모양으로 오는지 먼저 알아두면 훨씬 빨리 알아챌 수 있습니다.</p>';
  h+='<h4 class="rb-h">이 사주에 오는 권태기의 모양</h4>';
  h+='<p class="rb-p">'+MARR_CRISIS_BR[R.dBranch]+'</p>';
  h+='<p class="rb-p">여기에 <b>'+c.topGrp+'</b>의 결이 더해져, 이 사주는 '+(c.topGrp==='인성'?'혼자 생각을 정리하다 결론을 먼저 내리는 쪽':(c.topGrp==='관성'?'참고 견디다 어느 날 단호하게 정리하는 쪽':(c.topGrp==='식상'?'불만을 말로 다 쏟고 나서 후회하는 쪽':(c.topGrp==='재성'?'현실의 조건이 맞지 않는다고 판단하면 마음을 접는 쪽':'자존심 때문에 먼저 손을 내밀지 못하는 쪽'))))+'으로 흐릅니다. 그래서 상대는 “갑자기”라고 느끼지만, 이 사주 안에서는 오래전부터 정리된 일이에요.</p>';
  var danger=[];
  for(var i=0;i<R.seun.length;i++){
    var diff=mod(R.seun[i].idx%12-R.dBranch,12);
    if(diff===6) danger.push(R.seun[i].year);
  }
  h+='<h4 class="rb-h">이혼수 점검 — 시기보다 구조</h4>';
  h+='<p class="rb-p">명리에서 말하는 이혼수는 “이혼한다”는 예언이 아니라 <b>관계가 흔들리는 해</b>를 가리킵니다. '+(danger.length?('앞으로 5년 중 일지와 충하는 해는 <b>'+danger.join(', ')+'년</b>이에요. 이 해에는 이사·이직·별거 같은 생활의 변화가 겹치기 쉬워, 작은 갈등이 크게 느껴집니다. 큰 결정은 그해를 넘겨서 하세요.'):('앞으로 5년에는 일지와 직접 충하는 해가 없어요. 대신 갈등이 쌓이는 구조를 먼저 점검하세요.'))+'</p>';
  h+='<p class="rb-p">이혼을 결정하기 전에 스스로에게 물어볼 세 가지가 있어요. 첫째, <b>상대가 바뀌지 않아도 내가 견딜 수 있는가.</b> 둘째, <b>이 관계에서 내가 잃은 것이 나인지 상대인지.</b> 셋째, <b>지금 결정하면 1년 뒤의 내가 고마워할까.</b> 이 세 질문에 답이 정리되면, 남을지 떠날지가 아니라 <b>어떻게 살지</b>가 보입니다.</p>';
  if(pc){
    var br=branchRel(R.dBranch,pc.R.dBranch);
    h+='<p class="rb-p">두 사람의 일지는 <b>'+br.k+'</b>예요. '+br.t+' 갈등이 생기면 감정의 크기보다 <b>생활의 규칙</b>을 다시 정하는 쪽이 회복에 빠릅니다.</p>';
  }
  h+='<h4 class="rb-h">위기를 넘기는 세 가지</h4>';
  h+='<ul class="rb-ul">'+
    '<li><b>말의 시간을 정하세요.</b> 화가 난 날은 24시간 뒤에 이야기한다고 약속하세요. 이 사주는 그 하루가 지나면 절반이 정리됩니다.</li>'+
    '<li><b>문제를 하나로 좁히세요.</b> 오래된 일을 함께 꺼내면 대화가 재판이 됩니다. 이번 주에 있었던 일 하나만 다루세요.</li>'+
    '<li><b>같이 하는 일을 하나 만드세요.</b> 대화가 막히면 몸을 같이 움직이는 게 낫습니다. 산책·요리·운동처럼 말이 없어도 되는 시간이 관계를 다시 잇습니다.</li>'+
  '</ul>';
  h+='<p class="rb-warn">이 장은 명리학의 상징을 관계의 언어로 옮긴 참고 해석입니다. 이혼·별거 같은 결정의 근거가 아니며, 실제 판단은 두 사람과 필요하다면 전문 상담의 몫입니다.</p>';
  h+='<h4 class="rb-h">권태기의 신호 다섯</h4>';
  h+='<ul class="rb-ul">'+
    '<li>같이 있어도 <b>각자 화면</b>을 보는 시간이 늘어난다.</li>'+
    '<li>싸우지 않는데 <b>대화가 줄어든다</b>. 이 사주에게는 이쪽이 더 위험해요.</li>'+
    '<li>상대의 하루가 <b>궁금하지 않아진다</b>.</li>'+
    '<li>함께하는 일정을 <b>미루고 싶어진다</b>.</li>'+
    '<li>혼자 있는 상상을 <b>자주</b> 한다.</li>'+
  '</ul>';
  h+='<p class="rb-p">세 개 이상 해당되면, 관계가 나쁜 것이 아니라 <b>관리가 멈춘 상태</b>예요. 이 사주는 이 상태를 오래 두면 조용히 결론을 내립니다. 그 전에 한 번, “요즘 우리 어때”를 물어보세요.</p>';
  h+='<div class="rb-key"><b>위기 한 줄</b><span>위기는 사랑이 없어서 오는 게 아니라, 말이 멈춰서 옵니다. 한 문장을 먼저 꺼내는 쪽이 관계를 살립니다.</span></div>';
  return h;
}

function chCoupleSolution(R,c,input,name){
  var pc=partnerChart(input), h='';
  h+='<p class="rb-p">오래 가는 부부는 성격이 잘 맞는 사람들이 아니라, <b>어긋나는 방식을 아는 사람들</b>이에요. 이 사주의 결에 맞는 소통법과 역할 배분을 정리했습니다.</p>';
  h+='<h4 class="rb-h">역할 배분</h4>';
  h+='<p class="rb-p">'+MARR_SOLUTION[c.topGrp]+'</p>';
  h+='<p class="rb-p">이 사주는 <b>'+GOD_KEY[c.topGodInGrp]+'</b>이 강점이에요. 그래서 살림에서도 그 부분을 맡을 때 빛납니다. '+GOD_DEEP[c.topGodInGrp]+'</p>';
  if(pc){
    h+='<p class="rb-p">상대는 <b>'+pc.c.topGrp+'</b>의 결이라 '+MARR_SOLUTION[pc.c.topGrp]+' 두 사람이 같은 일을 나눠 하면 서로의 방식이 달라 다툽니다. <b>영역을 나누고 그 안에서는 간섭하지 않는 것</b>이 이 궁합의 핵심이에요.</p>';
  }
  h+='<h4 class="rb-h">대화의 규칙 세 가지</h4>';
  h+='<ul class="rb-ul">'+
    '<li><b>하루 15분</b> — 화면 없이 서로의 하루를 말하는 시간. 이 사주는 짧고 자주가 길고 드문 것보다 효과적이에요.</li>'+
    '<li><b>확인 질문</b> — “네 말은 ○○라는 뜻이야?”를 하루에 한 번. 이 사주는 자기 해석으로 먼저 결론을 내는 습관이 있어요.</li>'+
    '<li><b>고마움 한 번</b> — 당연한 일에 한 번씩 말로 고마움을 표시하세요. 이 사주는 챙긴 것이 당연해질 때 마음이 식습니다.</li>'+
  '</ul>';
  h+='<h4 class="rb-h">싸웠을 때의 매뉴얼</h4>';
  h+='<p class="rb-p">1) 그날은 결론을 내지 않습니다. 2) 다음 날, 그 일이 아니라 <b>그때의 감정</b>을 말합니다. 3) 상대의 말을 한 문장으로 되돌려줍니다. 4) 다음에 어떻게 할지 <b>하나만</b> 정합니다. 이 순서를 정해두면 같은 싸움이 반복되지 않아요.</p>';
  h+='<h4 class="rb-h">역할 분담표</h4>';
  h+='<p class="rb-p">이 사주의 강점은 <b>'+GOD_KEY[c.topGodInGrp]+'</b>이에요. 그래서 살림에서도 그 부분을 맡을 때 빛납니다. '+GOD_DEEP[c.topGodInGrp]+' 반대로 이 사주가 약한 영역('+EL_DEEP[c.leastI].part+' 쪽으로 상징되는 일)은 상대에게 맡기고 간섭하지 않는 편이 좋아요.</p>';
  h+='<ul class="rb-ul">'+
    '<li><b>나</b> — '+WORK_BY_GRP[c.topGrp].split(',')[0]+' 관련된 결정과 정리.</li>'+
    '<li><b>상대</b> — 내가 지치기 쉬운 영역. 이 영역은 “네가 정해”라고 말해주세요.</li>'+
    '<li><b>둘 다</b> — 돈의 큰 결정과 양가 일정. 이 두 가지는 반드시 함께 정합니다.</li>'+
  '</ul>';
  h+='<h4 class="rb-h">월간 대화</h4>';
  h+='<p class="rb-p">한 달에 한 번, 30분만 앉아 세 가지를 이야기하세요. ① 이번 달 서운했던 것 하나 ② 고마웠던 것 하나 ③ 다음 달 함께 하고 싶은 것 하나. 이 사주는 이 구조 안에서 감정을 말할 때 가장 편안해합니다.</p>';
  h+='<div class="rb-key"><b>부부 솔루션 한 줄</b><span>역할은 나누고, 감정은 나누지 마세요. 감정은 나눌수록 커지고, 역할은 나눌수록 가벼워집니다.</span></div>';
  return h;
}

function chMarriage5y(R,c,input,name){
  var h='';
  h+='<p class="rb-p">부부운도 5년 단위로 보면 흐름이 보입니다. 세운이 배우자성과 어떻게 만나는지, 일지와 부딪히는 해가 언제인지를 함께 놓고 보세요.</p>';
  h+='<h4 class="rb-h">향후 5년</h4>';
  for(var i=0;i<R.seun.length;i++){
    var sn=R.seun[i], s=sn.idx%10, b=sn.idx%12, g=tenGod(R.dStem,s), grp=GOD_GROUP[g];
    var diff=mod(b-R.dBranch,12), ex='';
    if(diff===6) ex='일지와 충하는 해라 생활의 판이 바뀌기 쉬워요. 이사·별거·가족 변화가 겹치면 대화를 더 자주 하세요.';
    else if(diff===0) ex='일지와 같은 글자가 오는 해라 예전의 문제가 다시 올라옵니다. 그때 미뤄둔 이야기를 이번에는 끝내세요.';
    else if(diff===4||diff===8) ex='일지와 합이 오는 해라 두 사람 사이에 사람이 개입해 일이 풀립니다. 상견례·가족 행사에 좋아요.';
    else ex='일지와 크게 부딪히지 않는 해라 생활의 기반을 다지기 좋습니다.';
    h+='<div class="rb-yr"><div class="yh"><span class="y">'+sn.year+'</span><b>'+STEM_HAN[s]+BR_HAN[b]+'</b><span class="g">'+g+' · '+grp+'</span></div><p>'+(grp==='관성'?'부부 사이의 책임과 역할이 무거워지는 해예요. 양가 일정과 집안 결정을 미리 나누면 무리 없이 지나갑니다.':(grp==='재성'?'살림과 돈의 구조가 구체적으로 움직이는 해예요. 함께 예산을 보는 시간을 두세요.':(grp==='식상'?'부부가 함께 무언가를 만들거나 배우기 좋은 해예요. 새로운 취미가 관계를 살립니다.':(grp==='인성'?'서로를 돌보는 마음이 커지는 해예요. 다만 참고 넘기면 서운함이 쌓입니다.':'각자의 자리를 확인하는 해예요. 가까울수록 예의를 지키면 부딪힘이 줄어듭니다.'))))+' '+ex+'</p></div>';
  }
  h+='<h4 class="rb-h">앞으로 12개월</h4>';
  h+=monthFlow(R,c,'marriage',12,'');
  h+='<p class="rb-p">이 5년을 한 문장으로 줄이면, <b>'+name+' 님의 부부운은 '+GOD_KEY[c.topGodInGrp]+'을 얼마나 부드럽게 쓰느냐</b>에 달려 있어요. 상대를 바꾸려는 대신 내 말투를 한 번 낮추는 해로 쓰면, 다음 5년이 훨씬 편해집니다.</p>';
  h+='<div class="rb-key"><b>5년 한 줄</b><span>가장 중요한 해는 충이 오는 해입니다. 그해에는 결정을 미루고, 대화를 늘리세요.</span></div>';
  return h;
}

