 '편관':'압박을 이기고 얻는 돈. 책임이 큰 자리에서 보상이 따라오지만, 몸을 담보로 버는 돈은 오래가지 않습니다.',
 '정관':'자리와 신뢰가 만드는 돈. 직함·자격·계약이 곧 수입이고, 조직에서 안정적으로 커집니다.',
 '편인':'생각과 기술이 돈이 되는 구조. 한 분야를 깊게 파는 쪽에서 수입이 나고, 시작은 느립니다.',
 '정인':'배움과 사람의 도움으로 버는 돈. 자격·교육·연구 쪽에서 안정되고, 혼자 서두르면 멀어집니다.'
